async function bootStart(){showFlow('pageFlowDb');updateFlowDb(10,'Menghubungkan ke database...');await applyLoadingBanners();try{const paths=['warungdigital/products','warungdigital/users','warungdigital/orders','warungdigital/download','warungdigital/settings','warungdigital/introWeb','warungdigital/uiInfo','warungdigital/vouchers','warungdigital/follows','warungdigital/promoweb'];let done=0;for(const p of paths){await db.ref(p).once('value');done++;updateFlowDb(10+Math.round((done/paths.length)*85),'Memuat '+p.split('/').pop()+'...')}updateFlowDb(100,'Selesai!');dbReady=true;await new Promise(r=>setTimeout(r,300));if(!dbSkipClicked)hideFlow('pageFlowDb');await loadBannerStage()}catch(e){console.warn(e);dbReady=true;if(!dbSkipClicked)hideFlow('pageFlowDb');await loadBannerStage()}}

async function loadBannerStage(){showFlow('pageFlowBanner');const set=(p,t)=>{const b=document.getElementById('flowBannerBar');const s=document.getElementById('flowBannerStatus');if(b)b.style.width=p+'%';if(s)s.textContent=t};set(20,'Memuat setting...');await loadAllBannersAndBg();set(50,'Memuat intro...');await loadIntroData();set(70,'Memuat info UI...');await loadUiInfo();set(90,'Memuat promo...');await Promise.all([loadPromoJualan(),loadPromoMedsos()]);set(100,'Selesai!');await new Promise(r=>setTimeout(r,200));hideFlow('pageFlowBanner');startIntro()}

async function applyLoadingBanners(){try{const snap=await db.ref('warungdigital/settings').once('value');const s=snap.val()||{};if(s.loadingBg){const dbPage=document.getElementById('pageFlowDb');const bannerPage=document.getElementById('pageFlowBanner');dbPage.style.backgroundImage=`url('${cdnImg(s.loadingBg,1200)}')`;bannerPage.style.backgroundImage=`url('${cdnImg(s.loadingBg,1200)}')`}if(s.loadingCircle){const logo3d=document.getElementById('loadingLogo');const spinner=document.getElementById('loadingCircle');if(logo3d){logo3d.classList.add('custom-logo');logo3d.innerHTML=`<img src="${cdnImg(s.loadingCircle,200)}" />`}if(spinner){spinner.classList.add('custom-spinner');spinner.innerHTML=`<img src="${cdnImg(s.loadingCircle,200)}" />`}}}catch(e){}}

async function loadAllBannersAndBg(){try{const snap=await db.ref('warungdigital/settings').once('value');const s=snap.val()||{};applyBannerImgVid('banner11','banner11Img',s.banner11);applyBannerImgVid('judulWebBanner','judulWebImg',s.bannerJudul);applyBannerImgVid('bannerAnimasiRB','bannerAnimasiImg',s.bannerAnimasi);applyLogo(s.bannerLogo);applyFavicon(s.favicon);applyBg(s.bgWeb)}catch(e){}}
function applyBannerImgVid(wrapId,imgId,url){const wrap=document.getElementById(wrapId);const img=document.getElementById(imgId);if(!wrap)return;if(url){wrap.classList.add('show');if(img){img.style.display='block';img.src=cdnImg(url,600);img.loading='lazy'}}else wrap.classList.remove('show')}
function applyLogo(url){const img=document.getElementById('logoNavImg');const fb=document.getElementById('logoNavFallback');if(!url){fb.style.display='block';img.style.display='none';return}fb.style.display='none';img.style.display='block';img.src=cdnImg(url,200)}
function applyFavicon(url){const link=document.querySelector('link[rel="icon"]');if(link&&url)link.href=cdnImg(url,64)}
function applyBg(url){document.body.classList.remove('has-bg');document.getElementById('bgStyle')?.remove();if(!url)return;const st=document.createElement('style');st.id='bgStyle';st.textContent=`body{background-image:url('${cdnImg(url,1200)}');background-size:cover;background-attachment:fixed}`;document.head.appendChild(st)}
