function startIntro(){if(currentUser&&hasSeenIntro){afterAuthGo();return}const hasMedia=introData.media&&introData.mediaType;if(!hasMedia){showIntroInfo();return}showFlow('pageIntroMedia');const img=document.getElementById('introImg');const vid=document.getElementById('introVid');const soundHint=document.getElementById('introSoundHint');img.style.display='none';vid.style.display='none';if(introData.mediaType==='video'){vid.style.display='block';vid.src=introData.media;vid.muted=false;vid.volume=1;vid.onended=()=>showIntroInfo();vid.play().catch(()=>{vid.muted=true;vid.play().then(()=>soundHint.classList.add('show')).catch(()=>{soundHint.classList.add('show');setTimeout(showIntroInfo,3000)})});setTimeout(()=>{if(document.getElementById('pageIntroMedia').classList.contains('show'))showIntroInfo()},30000)}else{img.style.display='block';img.src=introData.media;setTimeout(showIntroInfo,3000)}}
function enableIntroSound(){const vid=document.getElementById('introVid');if(vid){vid.muted=false;vid.play().catch(()=>{})}document.getElementById('introSoundHint').classList.remove('show')}
function showIntroInfo(){hideFlow('pageIntroMedia');setTimeout(()=>{showFlow('pageIntroInfo');document.getElementById('introInfoTitle').textContent=uiInfoData.title||'WarungDigital v8.3.1';document.getElementById('introInfoSubtitle').textContent=uiInfoData.subtitle||'Marketplace Produk Digital';const updates=uiInfoData.updates?Object.values(uiInfoData.updates):[];let html='';if(updates.length>0){html+='<div class="intro-info-card"><h3>📝 Update</h3>';updates.forEach(u=>{html+=`<div class="intro-update-item"><div class="dot"></div><div>${escapeHtml(u)}</div></div>`});html+='</div>'}else{html+='<div class="intro-info-card"><h3>📝 Update v8.3.1</h3><div class="intro-update-item"><div class="dot"></div><div>Login Card System</div></div><div class="intro-update-item"><div class="dot"></div><div>Voucher dari Penjual</div></div><div class="intro-update-item"><div class="dot"></div><div>Follow Seller + Streak + Badge</div></div><div class="intro-update-item"><div class="dot"></div><div>Flash Sale + Private Server + Promosi Web</div></div><div class="intro-update-item"><div class="dot"></div><div>Vopkhyah Easter Egg</div></div></div>'}document.getElementById('introInfoContent').innerHTML=html},400)}
