function switchLoginMethod(method){const mT=document.getElementById('loginMethodManual');const cT=document.getElementById('loginMethodCard');const mF=document.getElementById('loginManualForm');const cF=document.getElementById('loginCardForm');if(method==='manual'){mT.classList.add('active');cT.classList.remove('active');mF.style.display='block';cF.style.display='none'}else{mT.classList.remove('active');cT.classList.add('active');mF.style.display='none';cF.style.display='block'}}

async function doAuthSubmit(){const nama=document.getElementById('authNama').value.trim();const pass=document.getElementById('authPass').value.trim();if(!nama||!pass){showToast('Isi semua!','error');return}if(authMode==='register'){if(pass.length<4){showToast('Password min 4!','error');return}const snap=await db.ref('warungdigital/users/'+nama).once('value');if(snap.exists()){showToast('Nama udah dipake!','error');return}await db.ref('warungdigital/users/'+nama).set({password:pass,createdAt:Date.now(),ewallets:[],wa:'',exp:0,level:1,missions:{},achievements:{},follows:{},streak:{current:0,last:0,max:0},status:''});currentUser=nama;isGuest=false;localStorage.setItem('wd_user',nama);sessionStorage.setItem('wd_seen_intro','true');showToast('🎉 Daftar berhasil!','success');hideFlow('pageAuth');setTimeout(()=>showCardDownloadPage(nama,pass),400)}else{const snap=await db.ref('warungdigital/users/'+nama).once('value');if(!snap.exists()){showToast('❌ Akun gak terdaftar!','error');return}const u=snap.val();if(u.password!==pass){showToast('Password salah!','error');return}currentUser=nama;isGuest=false;localStorage.setItem('wd_user',nama);sessionStorage.setItem('wd_seen_intro','true');showToast('Login berhasil!','success');hideFlow('pageAuth');setTimeout(afterAuthGo,400)}}

function generateCardContent(userData){const idCard='CXZ-'+Math.random().toString(36).substring(2,10).toUpperCase();return{idCard,content:['═══════════════════════════════════════','   WARUNGDIGITAL v8.3.1 LOGIN CARD','═══════════════════════════════════════','ID CARD  : '+idCard,'Nama     : '+userData.nama,'Password : '+userData.password,'Dibuat   : '+new Date().toLocaleString('id-ID'),'═══════════════════════════════════════','⚠️ JANGAN BAGIKAN FILE INI!','⚠️ Satu-satunya cara login.','═══════════════════════════════════════'].join('\n')}}
function showCardDownloadPage(nama,password){const card=generateCardContent({nama,password});pendingCardData={nama,password,idCard:card.idCard,content:card.content,downloaded:false};document.getElementById('cardFileName').textContent='warungdigital-card-'+nama+'.txt';document.getElementById('cardFileSize').textContent=(new Blob([card.content]).size/1024).toFixed(2)+' KB';document.getElementById('cardDownloadBtn').classList.remove('done');document.getElementById('cardDownloadBtnText').textContent='Download Card Login';const cB=document.getElementById('cardContinueBtn');cB.disabled=true;cB.style.opacity='.4';showFlow('pageCardDownload');setTimeout(()=>{if(pendingCardData&&!pendingCardData.downloaded)downloadLoginCard(true)},1000)}
function downloadLoginCard(auto){if(!pendingCardData){showToast('Card gak ada!','error');return}const blob=new Blob([pendingCardData.content],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='warungdigital-card-'+pendingCardData.nama+'.txt';document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);pendingCardData.downloaded=true;document.getElementById('cardDownloadBtn').classList.add('done');document.getElementById('cardDownloadBtnText').textContent='✅ Downloaded!';const cB=document.getElementById('cardContinueBtn');cB.disabled=false;cB.style.opacity='1';if(!auto)showToast('✅ Card ter-download!','success');if(currentUser){db.ref('warungdigital/logincards/'+currentUser).set({idCard:pendingCardData.idCard,nama:pendingCardData.nama,createdAt:Date.now(),lastDownload:Date.now()})}}
function continueFromCardPage(){if(!pendingCardData||!pendingCardData.downloaded){showToast('Download dulu!','error');return}hideFlow('pageCardDownload');setTimeout(afterAuthGo,400)}
function readCardFile(input){const file=input.files[0];if(!file)return;if(!file.name.endsWith('.txt')){showToast('File harus .txt!','error');return}const reader=new FileReader();reader.onload=e=>{const parsed=parseCardContent(e.target.result);if(!parsed){showToast('❌ File gak valid!','error');return}document.getElementById('cardUploadArea').classList.add('has-file');document.getElementById('cardUploadFilename').textContent='✅ '+file.name;document.getElementById('cardUploadFilename').style.display='block';document.getElementById('cardLoginBtn').disabled=false;document.getElementById('cardLoginBtn').style.opacity='1';pendingCardData={nama:parsed.nama,password:parsed.password};showToast('✅ File terbaca!','success')};reader.readAsText(file)}
function parseCardContent(content){const lines=content.split('\n');let nama=null,password=null;lines.forEach(l=>{const t=l.trim();if(t.startsWith('Nama'))nama=t.split(':')[1]?.trim();if(t.startsWith('Password'))password=t.split(':')[1]?.trim()});if(!nama||!password)return null;return{nama,password}}
async function doCardLogin(){if(!pendingCardData||!pendingCardData.nama){showToast('Upload file!','error');return}const snap=await db.ref('warungdigital/users/'+pendingCardData.nama).once('value');if(!snap.exists()){showToast('❌ Akun gak ditemukan!','error');return}const u=snap.val();if(u.password!==pendingCardData.password){showToast('❌ Password gak cocok!','error');return}currentUser=pendingCardData.nama;isGuest=false;localStorage.setItem('wd_user',currentUser);sessionStorage.setItem('wd_seen_intro','true');showToast('✅ Login via card!','success');hideFlow('pageAuth');setTimeout(afterAuthGo,400)}

async function afterAuthGo(){showApp();showPage('home');if(currentUser){setTimeout(()=>{if(oneSignalReady)window.OneSignal.login(currentUser).catch(()=>{})},1000);await loadUserData();await checkDevStatus();await checkDailyReset();await checkStreak();await logMission('login');await checkAchievement('first_login');checkVirusOnLoad();db.ref('warungdigital/users/'+currentUser).on('value',snap=>{if(!snap.exists()){showTopNotif('❌ Akun Dihapus','Akun lo dihapus Dev','error');setTimeout(()=>{currentUser=null;localStorage.removeItem('wd_user');location.reload()},3000)}});db.ref('warungdigital/notifications').orderByChild('target').equalTo(currentUser).limitToLast(10).on('child_added',snap=>{const n=snap.val();if(!n||n.read)return;showTopNotif(n.title,n.message,n.type==='danger'?'error':'info');snap.ref.update({read:true})});startUnreadChatListener()}}
async function loadUserData(){if(!currentUser)return;const snap=await db.ref('warungdigital/users/'+currentUser).once('value');if(!snap.exists)return;userData=snap.val();userExp=userData.exp||0;userLevel=userData.level||1;userMissions=userData.missions||{};userAchievements=userData.achievements||{};userFollows=userData.follows||{};userStreak=userData.streak||{current:0,last:0,max:0};updateLevelUI()}

function updateLevelUI(){const el=document.getElementById('levelPageContent');if(!el)return;const lvInfo=getLevelInfo(userLevel);const nextLv=LEVELS[userLevel]||null;const expForNext=nextLv?nextLv.expNeed:0;const expTotalForLevel=LEVELS.slice(0,userLevel-1).reduce((a,b)=>a+b.expNeed,0);const expInLevel=userExp-expTotalForLevel;const pct=expForNext>0?Math.min(100,Math.round(expInLevel/expForNext*100)):100;const todayMissionIds=Object.keys(userMissions);el.innerHTML=`<div class="level-card"><div class="level-header"><div class="level-badge">${emoji('em-trophy','em')} Level ${userLevel}</div><div style="font-size:13px;opacity:.7">Total EXP: <strong style="color:#25d366">${userExp.toLocaleString('id-ID')}</strong></div></div><div style="font-size:16px;font-weight:800;margin-bottom:12px">${escapeHtml(lvInfo.name)}</div><div class="exp-bar-wrap"><div class="exp-bar" style="width:${pct}%"></div></div><div class="exp-text"><span>EXP: <span class="exp-now">${expInLevel.toLocaleString('id-ID')}</span> / ${expForNext.toLocaleString('id-ID')}</span><span>${pct}%</span></div>${nextLv?'<div class="level-name">Next: Level '+nextLv.lv+'</div>':'<div class="level-name">🎉 MAX</div>'}</div><div class="section-header" style="margin-top:20px"><h2 style="font-size:18px">${emoji('em-trophy','em')} Leaderboard</h2></div><div id="leaderboardContainer"><div class="empty"><p>Memuat...</p></div></div><div class="section-header" style="margin-top:20px"><h2 style="font-size:18px">${emoji('em-bolt','em')} Misi Harian</h2></div><div>${MISSIONS.map(m=>{const done=todayMissionIds.includes(m.id);return `<div class="mission-item ${done?'done':''}"><div class="icon">${m.icon}</div><div class="info"><div class="nama">${escapeHtml(m.name)}</div><div class="desc">${escapeHtml(m.desc)}</div></div><div class="reward">${done?'✅':'+'+m.exp}</div></div>`}).join('')}</div>`;loadLeaderboard()}
async function loadLeaderboard(){const el=document.getElementById('leaderboardContainer');if(!el)return;try{const snap=await db.ref('warungdigital/users').once('value');const users=snap.val()||{};const arr=Object.entries(users).map(([nama,u])=>({nama,exp:u.exp||0,level:u.level||1,isDev:u.isDev||false})).filter(u=>!u.isDev);arr.sort((a,b)=>b.exp-a.exp);const top10=arr.slice(0,10);if(top10.length===0){el.innerHTML='<div class="empty"><p>Belum ada user</p></div>';return}const medals=['🥇','🥈','🥉'];el.innerHTML=top10.map((u,i)=>{const cls=i===0?'top1':i===1?'top2':i===2?'top3':'';const rank=i<3?medals[i]:('#'+(i+1));return `<div class="leaderboard-item ${cls}"><div class="rank">${rank}</div><div class="avatar">${u.nama.charAt(0).toUpperCase()}</div><div class="info"><div class="nama">${escapeHtml(u.nama)}${u.nama===currentUser?' (Lo)':''}</div><div class="meta">Lv ${u.level}</div></div><div class="exp">${u.exp.toLocaleString('id-ID')}</div></div>`}).join('')}catch(e){el.innerHTML='<div class="empty"><p>Gagal load</p></div>'}}

async function addExp(amount,reason){if(!currentUser||isGuest)return;const oldLevel=userLevel;userExp+=amount;userLevel=getLevelFromExp(userExp);await db.ref('warungdigital/users/'+currentUser).update({exp:userExp,level:userLevel});if(userLevel>oldLevel){showTopNotif('🎉 LEVEL UP!','Level '+userLevel+' - '+getLevelInfo(userLevel).name,'success');const fn=SOUNDS.levelup[userLevel];if(fn)fn();if(userLevel>=5)checkAchievement('lvl5');if(userLevel>=7)checkAchievement('lvl7')}updateLevelUI()}
async function checkDailyReset(){if(!currentUser)return;const lastReset=userData?.lastMissionReset||0;if(Date.now()-lastReset>=24*60*60*1000){await db.ref('warungdigital/users/'+currentUser).update({missions:{},lastMissionReset:Date.now()});userMissions={}}}
async function checkStreak(){if(!currentUser||isGuest)return;const today=new Date().toDateString();const last=userStreak.last?new Date(userStreak.last).toDateString():null;if(last===today)return;const yesterday=new Date(Date.now()-86400000).toDateString();let current=userStreak.current||0;if(last===yesterday)current++;else current=1;const max=Math.max(userStreak.max||0,current);userStreak={current,last:Date.now(),max};await db.ref('warungdigital/users/'+currentUser).update({streak:userStreak});const bonus=50*current;await addExp(bonus,'Streak hari ke-'+current);if(current>=7)checkAchievement('streak7')}
async function logMission(missionId){if(!currentUser||isGuest)return;if(userMissions[missionId])return;const m=MISSIONS.find(x=>x.id===missionId);if(!m)return;userMissions[missionId]=true;await db.ref('warungdigital/users/'+currentUser).update({missions:userMissions});await addExp(m.exp,'Misi: '+m.name)}
async function checkAchievement(id){if(!currentUser||isGuest)return;if(userAchievements[id])return;const a=ACHIEVEMENTS.find(x=>x.id===id);if(!a)return;userAchievements[id]=true;await db.ref('warungdigital/users/'+currentUser).update({achievements:userAchievements});showTopNotif('🏅 ACHIEVEMENT!',a.icon+' '+a.name,'success')}

async function ensureDevAccount(){const snap=await db.ref('warungdigital/users/'+DEV_NAME).once('value');if(!snap.exists()){await db.ref('warungdigital/users/'+DEV_NAME).set({password:DEV_PASS,createdAt:Date.now(),ewallets:[],wa:'',exp:999999,level:999,missions:{},achievements:{},follows:{},streak:{current:0,last:0,max:0},isDev:true,status:'Developer'})}else{await db.ref('warungdigital/users/'+DEV_NAME).update({isDev:true,level:999})}}
async function checkDevStatus(){if(!currentUser){isDev=false;return}const snap=await db.ref('warungdigital/users/'+currentUser+'/isDev').once('value');isDev=snap.val()===true||currentUser===DEV_NAME}
function openTopbar(){document.getElementById('topbar').classList.add('open');document.getElementById('topbarOverlay').classList.add('show');document.getElementById('topbarGrid').innerHTML=buildTopbarMenu()}
function closeTopbar(){document.getElementById('topbar').classList.remove('open');document.getElementById('topbarOverlay').classList.remove('show')}
function buildTopbarMenu(){const items=[{icon:'em-box',label:'Home',page:'home'},{icon:'em-store',label:'Jualan',page:'jualan'},{icon:'em-cart',label:'Keranjang',page:'cart'},{icon:'em-receipt',label:'History',page:'orders'},{icon:'em-wallet',label:'Dompet',page:'dompet'},{icon:'em-cloud',label:'Download',page:'download'},{icon:'em-heart',label:'Wishlist',page:'wishlist'},{icon:'em-trophy',label:'Level',page:'level'},{icon:'em-fire',label:'Flash Sale',page:'flashsale'},{icon:'em-tag',label:'Voucher',page:'voucher'},{icon:'em-heart',label:'Following',page:'following'},{icon:'em-fire',label:'Streak',page:'streak'},{icon:'em-trophy',label:'Badge',page:'achievements'},{icon:'em-info',label:'Statistik',page:'statistik'},{icon:'em-link',label:'Promosi Web',page:'promoweb'},{icon:'em-server',label:'Private Server',page:'privateserver'},{icon:'em-user',label:'Info Akun',page:'accounts'},{icon:'em-send',label:'Chat',page:'chatlist'},{icon:'em-user',label:'Setting',page:'account'},{icon:'em-bulb',label:'Request',onclick:'showRequestFitur()'},{icon:'em-help',label:'Help',onclick:'showHelp()'}];let html=items.map(i=>`<button class="menu-btn" onclick="${i.onclick||`showPage('${i.page}');closeTopbar()`}"><svg><use href="#${i.icon}"/></svg> ${i.label}</button>`).join('');if(isDev){html+='<button class="menu-btn dev" onclick="showPage(\'dev\');closeTopbar()"><svg><use href="#em-crown"/></svg> Dev Panel</button>'}if(currentUser){html+='<button class="menu-btn" onclick="logoutUser();closeTopbar()"><svg><use href="#em-logout"/></svg> Logout</button>'}else{html+='<button class="menu-btn" onclick="showAuthPage(\'login\');closeTopbar()"><svg><use href="#em-login"/></svg> Login</button>'}return html}
function logoutUser(){if(!confirm('Yakin logout?'))return;if(oneSignalReady)window.OneSignal.logout().catch(()=>{});currentUser=null;isGuest=false;localStorage.removeItem('wd_user');sessionStorage.removeItem('wd_seen_intro');isDev=false;setTimeout(()=>location.reload(),300)}

function saveCart(){localStorage.setItem('wd_cart',JSON.stringify(cart));updateCartBadge()}
function updateCartBadge(){const badge=document.getElementById('cartBadge');if(!badge)return;const total=cart.reduce((a,b)=>a+b.qty,0);if(total>0){badge.style.display='block';badge.textContent=total}else badge.style.display='none'}
function addToCart(id){const p=products[id];if(!p)return;if(!currentUser||isGuest){showToast('Login dulu!','error');showAuthPage('login');return}if(p.penjual===currentUser){showToast('Gak bisa beli sendiri!','error');return}if(p.stock!==undefined&&p.stock!==null&&p.stock<=0){showToast('Stok habis!','error');return}const ex=cart.find(c=>c.id===id);if(ex)ex.qty++;else cart.push({id,nama:p.nama,harga:p.harga,penjual:p.penjual,qty:1});saveCart();showToast('Masuk keranjang!','success');if(currentPage==='cart')renderCart()}
function removeFromCart(i){cart.splice(i,1);saveCart();renderCart()}
function changeQty(i,d){cart[i].qty+=d;if(cart[i].qty<=0)cart.splice(i,1);saveCart();renderCart()}
function clearCart(){if(!confirm('Kosongin?'))return;cart=[];saveCart();renderCart()}

function showPage(page){currentPage=page;document.querySelectorAll('[id^="page-"]').forEach(el=>{if(el.classList.contains('page-flow'))return;el.classList.add('hidden')});const el=document.getElementById('page-'+page);if(el)el.classList.remove('hidden');const fn={home:renderHome,jualan:renderJualan,cart:renderCart,orders:renderOrders,dompet:renderDompet,download:renderDownload,wishlist:renderWishlist,level:renderLevelPage,flashsale:renderFlashSale,voucher:renderVoucher,following:renderFollowing,streak:renderStreak,achievements:renderAchievements,statistik:renderStatistik,promoweb:renderPromoWeb,privateserver:renderPrivateServer,accounts:renderAccounts,chatlist:renderChatList,account:loadSettingAccount,dev:renderDev};if(fn[page])fn[page]();window.scrollTo({top:0,behavior:'smooth'})}

db.ref('warungdigital/products').on('value',snap=>{products=snap.val()||{};const sp=document.getElementById('statProduk');const pc=document.getElementById('produkCount');if(sp)sp.textContent=Object.keys(products).length;if(pc)pc.textContent=Object.keys(products).length+' produk';if(dbReady&&currentPage==='home')renderHome();if(dbReady&&currentPage==='flashsale')renderFlashSale()});
db.ref('warungdigital/download').on('value',snap=>{downloadItems=snap.val()||{};if(dbReady&&currentPage==='download')renderDownload()});
db.ref('warungdigital/users').on('value',snap=>{const el=document.getElementById('statUser');if(el)el.textContent=snap.numChildren()});
db.ref('warungdigital/orders').on('value',snap=>{const count=snap.numChildren();const el=document.getElementById('statOrder');if(el)el.textContent=count;if(lastOrderCount>0&&count>lastOrderCount&&currentUser){snap.forEach(child=>{const o=child.val();if(o.penjual===currentUser&&o.status==='proof_uploaded'){showTopNotif('🛒 Pesanan Baru!',o.produkNama,'success');SOUNDS.order()}})}lastOrderCount=count});

function renderHome(){const grid=document.getElementById('productGrid');if(!grid)return;let list=Object.entries(products).map(([id,p])=>({id,...p}));const q=document.getElementById('searchProduk')?.value.trim().toLowerCase()||'';const kat=document.getElementById('filterKategori')?.value||'';const sort=document.getElementById('filterSort')?.value||'terbaru';if(q)list=list.filter(p=>(p.nama||'').toLowerCase().includes(q));if(kat)list=list.filter(p=>p.kategori===kat);if(sort==='terbaru')list.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));if(sort==='termurah')list.sort((a,b)=>(a.harga||0)-(b.harga||0));if(sort==='termahal')list.sort((a,b)=>(b.harga||0)-(a.harga||0));if(sort==='terlaris')list.sort((a,b)=>(b.sold||0)-(a.sold||0));if(list.length===0){grid.innerHTML='<div class="empty"><p>Belum ada produk</p></div>';return}grid.innerHTML=list.map(p=>{const inCart=cart.find(c=>c.id===p.id);const habis=p.stock!==undefined&&p.stock!==null&&p.stock<=0;const inWishlist=wishlist.includes(p.id);return `<div class="product-card" onclick="showDetail('${p.id}')"><div class="thumb">${p.banner?`<img src="${cdnImg(p.banner,500)}" loading="lazy">`:'📦'}</div><button class="wishlist-btn ${inWishlist?'active':''}" onclick="event.stopPropagation();toggleWishlist('${p.id}')">${inWishlist?'❤️':'🤍'}</button>${inCart?'<div class="badge-mini-cart">'+inCart.qty+'</div>':''}${habis?'<div class="badge-habis">HABIS</div>':''}${p.flashSale?'<div class="badge-flash">🔥</div>':''}<div class="info"><div class="kategori">${escapeHtml(p.kategori||'Umum')}</div><div class="nama">${escapeHtml(p.nama)}</div><div class="penjual">👤 ${escapeHtml(p.penjual)}</div><div class="meta"><span class="stok">📦 ${p.stock!==undefined&&p.stock!==null?p.stock:'∞'}</span><span class="sold">🛒 ${p.sold||0}</span></div><div class="harga"><span>${formatRp(p.harga)}</span><button class="btn-beli" onclick="event.stopPropagation();beliLangsung('${p.id}')">Beli</button></div></div></div>`}).join('')}
function toggleWishlist(id){const idx=wishlist.indexOf(id);if(idx>=0)wishlist.splice(idx,1);else wishlist.push(id);localStorage.setItem('wd_wishlist',JSON.stringify(wishlist));showToast(idx>=0?'Dihapus':'❤️ Ditambah!','success');if(currentPage==='home')renderHome();if(currentPage==='wishlist')renderWishlist()}
function renderWishlist(){const el=document.getElementById('wishlistGrid');const wc=document.getElementById('wishlistCount');if(!el)return;if(wc)wc.textContent=wishlist.length;const list=wishlist.map(id=>products[id]?{id,...products[id]}:null).filter(Boolean);if(list.length===0){el.innerHTML='<div class="empty"><p>Wishlist kosong</p></div>';return}el.innerHTML=list.map(p=>`<div class="product-card" onclick="showDetail('${p.id}')"><div class="thumb">${p.banner?`<img src="${cdnImg(p.banner,500)}">`:'📦'}</div><div class="info"><div class="nama">${escapeHtml(p.nama)}</div><div class="harga">${formatRp(p.harga)}</div></div></div>`).join('')}

async function showDetail(id){const p=products[id];if(!p)return;const habis=p.stock!==undefined&&p.stock!==null&&p.stock<=0;const isFollowed=userFollows[p.penjual];openModal(`<button class="close-btn" onclick="closeModal()">✕</button>${p.banner?`<img src="${cdnImg(p.banner,800)}" style="width:100%;border-radius:16px;margin-bottom:14px;max-height:200px;object-fit:cover" />`:''}<h2>${escapeHtml(p.nama)}</h2><div style="font-size:12px;opacity:.6;margin-bottom:8px">👤 ${escapeHtml(p.penjual)}</div><div style="font-size:28px;font-weight:900;color:#25d366;margin-bottom:12px">${formatRp(p.harga)}</div><p style="font-size:14px;opacity:.8;line-height:1.6;margin-bottom:16px;white-space:pre-wrap">${escapeHtml(p.deskripsi||'Tidak ada deskripsi.')}</p><div class="tabungan-grid" style="margin-bottom:16px"><div class="tabungan-item"><div class="label">Stok</div><div class="val">${p.stock!==undefined&&p.stock!==null?p.stock:'∞'}</div></div><div class="tabungan-item"><div class="label">Terjual</div><div class="val">${p.sold||0}</div></div></div><button class="btn btn-primary btn-block" onclick="${habis?"showToast('Habis!','error')":`beliLangsung('${id}')`}" ${habis?'disabled':''}>🛒 Beli</button><button class="btn btn-secondary btn-block" onclick="addToCart('${id}');closeModal()" ${habis?'disabled':''}>+ Keranjang</button><button class="btn btn-secondary btn-block" onclick="closeModal();openChatWith('${escapeHtml(p.penjual)}')">💬 Chat</button><button class="btn btn-secondary btn-block" onclick="toggleFollow('${escapeHtml(p.penjual)}')">${isFollowed?'❤️ Unfollow':'🤍 Follow'}</button>`)}

async function beliLangsung(id){if(!currentUser||isGuest){showToast('Login dulu!','error');showAuthPage('login');return}const p=products[id];if(!p)return;if(p.penjual===currentUser){showToast('Gak bisa beli sendiri!','error');return}if(p.tipe==='wa'&&p.waLink){window.open(p.waLink,'_blank');return}closeModal();const snap=await db.ref('warungdigital/users/'+p.penjual).once('value');const u=snap.val()||{};const ewallets=(u.ewallets||[]).filter(e=>e.verified);if(ewallets.length===0){showToast('Penjual belum punya e-wallet!','error');return}buktiUrl='';selectedEwallet=null;appliedVoucher=null;openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>🛒 Beli</h2><div class="verify-box"><div class="label">Produk</div><div class="val">${escapeHtml(p.nama)}</div><div class="label" style="margin-top:8px">Harga</div><div class="val big">${formatRp(p.harga)}</div></div><label>Voucher</label><div class="voucher-input-row"><input type="text" id="voucherInput" placeholder="KODE" /><button onclick="applyVoucher()">Pakai</button></div><div id="voucherApplied"></div><label>Pilih E-Wallet</label><div class="metode-list" id="ewalletList">${ewallets.map((e,i)=>`<div class="metode-item" onclick="pilihEwallet(${i},'${escapeHtml(e.jenis)}','${escapeHtml(e.namaAkun)}','${escapeHtml(e.nomor)}')">${e.jenis} — ${escapeHtml(e.namaAkun)}</div>`).join('')}</div><div id="ewalletDetail"></div><label style="margin-top:14px">Bukti TF</label><div class="upload-area" onclick="document.getElementById('buktiInput').click()"><div class="icon">${emoji('em-upload','em-2xl')}</div><div class="text">Klik upload</div><img id="buktiPreview" style="display:none" /></div><input type="file" id="buktiInput" accept="image/*" style="display:none" onchange="readBuktiFile(this,'${id}')" /><button class="btn btn-primary btn-block" onclick="submitBeliLangsung('${id}')">✅ Kirim</button>`)}
function pilihEwallet(i,jenis,namaAkun,nomor){selectedEwallet={jenis,namaAkun,nomor};document.querySelectorAll('#ewalletList .metode-item').forEach(x=>x.classList.remove('selected'));document.querySelectorAll('#ewalletList .metode-item')[i].classList.add('selected');document.getElementById('ewalletDetail').innerHTML=`<div class="verify-box"><div class="label">Nomor</div><div class="val big">${escapeHtml(nomor)}</div><div class="label" style="margin-top:8px">A/N</div><div class="val">${escapeHtml(namaAkun)}</div></div>`}
async function readBuktiFile(input,produkId){const file=input.files[0];if(!file)return;showUploadProgress('Upload Bukti');try{const res=await uploadToCloudinary(file,updateUploadProgress);buktiUrl=res.secure_url;closeModal();setTimeout(()=>beliLangsung(produkId),200)}catch(e){showToast('❌ '+e.message,'error');closeModal()}}
async function submitBeliLangsung(id){if(isSubmitting)return;if(!selectedEwallet){showToast('Pilih e-wallet!','error');return}if(!buktiUrl){showToast('Upload bukti!','error');return}isSubmitting=true;const p=products[id];let finalHarga=p.harga;if(appliedVoucher&&p.harga>=appliedVoucher.minBeli)finalHarga=p.harga-Math.round(p.harga*appliedVoucher.diskon/100);const orderId='ORD-'+Date.now();const isDevProduct=p.penjual===DEV_NAME;const order={orderId,produkId:id,produkNama:p.nama,harga:finalHarga,originalHarga:p.harga,total:finalHarga,pembeli:currentUser,penjual:p.penjual,ewallet:selectedEwallet,nominal:finalHarga,namaTujuan:selectedEwallet.namaAkun,bukti:buktiUrl,status:isDevProduct?'verified':'proof_uploaded',createdAt:Date.now(),voucher:appliedVoucher};if(isDevProduct&&p.linkMediafire)order.linkProduk=p.linkMediafire;await db.ref('warungdigital/orders/'+orderId).set(order);if(appliedVoucher){const vSnap=await db.ref('warungdigital/vouchers/'+appliedVoucher.id).once('value');const v=vSnap.val();if(v){const newCount=(v.usedCount||0)+1;await db.ref('warungdigital/vouchers/'+appliedVoucher.id).update({usedCount:newCount,used:newCount>=v.maxUse})}}closeModal();showToast('✅ Pesanan dikirim!','success');SOUNDS.order();const expAdd=finalHarga<=9000?100:finalHarga<=25000?250:finalHarga<=50000?500:1000;await addExp(expAdd,'Beli produk');await logMission('beli');await checkAchievement('first_buy');if(p.flashSale)await logMission('flashsale');buktiUrl='';selectedEwallet=null;appliedVoucher=null;isSubmitting=false;showPage('orders')}

async function applyVoucher(){const input=document.getElementById('voucherInput');if(!input)return;const kode=input.value.trim().toUpperCase();if(!kode){showToast('Masukkan kode!','error');return}const snap=await db.ref('warungdigital/vouchers').orderByChild('kode').equalTo(kode).once('value');if(!snap.exists()){showToast('❌ Gak valid','error');return}const v=Object.values(snap.val())[0];const vId=Object.keys(snap.val())[0];if(v.expired||(v.expiresAt&&Date.now()>v.expiresAt)){showToast('❌ Expired','error');return}if(v.used||(v.usedCount||0)>=v.maxUse){showToast('❌ Habis','error');return}if(v.penjual===currentUser){showToast('❌ Gak bisa pakai sendiri','error');return}appliedVoucher={id:vId,kode:v.kode,diskon:v.diskon,minBeli:v.minBeli};const el=document.getElementById('voucherApplied');if(el)el.innerHTML=`<div class="voucher-applied">🎟️ <strong>${v.kode}</strong> -${v.diskon}% <button onclick="removeVoucher()" style="background:transparent;border:none;color:#e74c3c;font-weight:900;cursor:pointer">✕</button></div>`;showToast('✅ Voucher diapply!','success')}
function removeVoucher(){appliedVoucher=null;const el=document.getElementById('voucherApplied');if(el)el.innerHTML=''}

function renderCart(){const el=document.getElementById('cartList');const cc=document.getElementById('cartCount');if(!el)return;if(cc)cc.textContent=cart.reduce((a,b)=>a+b.qty,0)+' item';if(cart.length===0){el.innerHTML='<div class="empty"><p>Keranjang kosong</p></div>';return}const total=cart.reduce((a,b)=>a+b.harga*b.qty,0);el.innerHTML=cart.map((c,i)=>`<div class="cart-item"><div class="thumb">📦</div><div class="info"><div class="nama">${escapeHtml(c.nama)}</div><div class="harga">${formatRp(c.harga)} × ${c.qty}</div></div><div class="qty"><button onclick="changeQty(${i},-1)">−</button><span>${c.qty}</span><button onclick="changeQty(${i},1)">+</button></div><button class="del" onclick="removeFromCart(${i})">🗑️</button></div>`).join('')+`<div class="cart-total"><span>Total</span><span class="total">${formatRp(total)}</span></div><button class="btn btn-primary btn-block" onclick="checkoutCart()">✅ Checkout</button><button class="btn btn-danger btn-block" onclick="clearCart()">🗑️ Kosongin</button>`}
async function checkoutCart(){if(cart.length===0){showToast('Keranjang kosong!','error');return}if(!currentUser||isGuest){showToast('Login dulu!','error');return}const total=cart.reduce((a,b)=>a+b.harga*b.qty,0);const firstSeller=cart[0].penjual;const snap=await db.ref('warungdigital/users/'+firstSeller).once('value');const u=snap.val()||{};const ewallets=(u.ewallets||[]).filter(e=>e.verified);if(ewallets.length===0){showToast('Penjual belum punya e-wallet!','error');return}openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>🛒 Checkout</h2><div class="verify-box"><div class="label">Total</div><div class="val big">${formatRp(total)}</div></div><label>E-Wallet</label><div class="metode-list" id="ewalletList">${ewallets.map((e,i)=>`<div class="metode-item" onclick="pilihEwallet(${i},'${escapeHtml(e.jenis)}','${escapeHtml(e.namaAkun)}','${escapeHtml(e.nomor)}')">${e.jenis} — ${escapeHtml(e.namaAkun)}</div>`).join('')}</div><div id="ewalletDetail"></div><button class="btn btn-primary btn-block" onclick="submitCartOrder()">✅ Kirim</button>`)}
async function submitCartOrder(){if(!selectedEwallet){showToast('Pilih e-wallet!','error');return}if(!buktiUrl){showToast('Upload bukti!','error');return}const total=cart.reduce((a,b)=>a+b.harga*b.qty,0);const orderId='ORD-'+Date.now();await db.ref('warungdigital/orders/'+orderId).set({orderId,items:cart.map(c=>({nama:c.nama,harga:c.harga,qty:c.qty,penjual:c.penjual})),produkNama:cart.map(c=>c.nama).join(', '),total,pembeli:currentUser,penjual:cart[0].penjual,ewallet:selectedEwallet,nominal:total,namaTujuan:selectedEwallet.namaAkun,bukti:buktiUrl,status:'proof_uploaded',createdAt:Date.now()});closeModal();showToast('✅ Dikirim!','success');cart=[];saveCart();selectedEwallet=null;buktiUrl='';showPage('orders')}

async function renderOrders(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}const el=document.getElementById('ordersList');if(!el)return;const snap=await db.ref('warungdigital/orders').limitToLast(100).once('value');const orders=[];snap.forEach(c=>{const o=c.val();if(o.pembeli===currentUser||o.penjual===currentUser)orders.push({key:c.key,...o})});orders.sort((a,b)=>b.createdAt-a.createdAt);const oc=document.getElementById('ordersCount');if(oc)oc.textContent=orders.length;if(orders.length===0){el.innerHTML='<div class="empty"><p>Belum ada history</p></div>';return}el.innerHTML=orders.map(o=>renderOrderCard(o,o.penjual===currentUser?'penjual':'pembeli')).join('')}
function renderOrderCard(o,role){const statusMap={proof_uploaded:{label:'⏳ Nunggu',cls:'status-waiting'},verified:{label:'✅ Selesai',cls:'status-verified'},cancelled:{label:'❌ Batal',cls:'status-cancelled'},refund:{label:'💸 Refund',cls:'status-refund'}};const st=statusMap[o.status]||statusMap.proof_uploaded;const time=new Date(o.createdAt).toLocaleString('id-ID');return `<div class="order-item"><div class="head"><div class="oid">${escapeHtml(o.orderId)}</div><div class="status ${st.cls}">${st.label}</div></div><div class="body">📦 ${escapeHtml(o.produkNama)}<br>💰 ${formatRp(o.total)}<br>👤 ${role==='pembeli'?'Penjual':'Pembeli'}: ${escapeHtml(role==='pembeli'?o.penjual:o.pembeli)}<br>📅 ${time}</div><div class="actions">${o.status==='proof_uploaded'&&role==='penjual'?`<button class="btn btn-sm btn-primary" onclick="confirmOrder('${o.key}')">✅ Konfirmasi</button><button class="btn btn-sm btn-danger" onclick="cancelOrder('${o.key}')">❌ Cancel</button>`:''}${o.status==='verified'&&role==='pembeli'&&o.linkProduk?`<a class="btn btn-sm btn-success" href="${o.linkProduk}" target="_blank">⬇️ Download</a>`:''}<button class="btn btn-sm btn-secondary" onclick="openChatWith('${role==='pembeli'?o.penjual:o.pembeli}')">💬 Chat</button></div></div>`}
async function confirmOrder(orderKey){if(!confirm('Konfirmasi?'))return;const snap=await db.ref('warungdigital/orders/'+orderKey).once('value');const o=snap.val();const produk=products[o.produkId];const update={status:'verified',confirmedAt:Date.now()};if(produk&&produk.linkMediafire)update.linkProduk=produk.linkMediafire;await db.ref('warungdigital/orders/'+orderKey).update(update);if(produk&&produk.stock!==undefined&&produk.stock!==null){await db.ref('warungdigital/products/'+o.produkId).update({stock:Math.max(0,(produk.stock||0)-1),sold:(produk.sold||0)+1})}showToast('✅ Dikonfirmasi!','success');await logMission('jual');await checkAchievement('first_sell');renderOrders();renderJualanPesanan()}
function cancelOrder(orderKey){openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2 style="color:#e74c3c">❌ Cancel</h2><label>Alasan</label><select id="cancelReasonSelect"><option value="">-- Pilih --</option><option>Bukti palsu</option><option>Nominal gak sesuai</option><option>Stok habis</option><option>Lainnya</option></select><button class="btn btn-danger btn-block" onclick="submitCancelOrder('${orderKey}')">❌ Cancel</button>`)}
async function submitCancelOrder(orderKey){const reason=document.getElementById('cancelReasonSelect').value;if(!reason){showToast('Pilih alasan!','error');return}await db.ref('warungdigital/orders/'+orderKey).update({status:'cancelled',cancelReason:reason,cancelledAt:Date.now(),cancelledBy:currentUser});closeModal();showToast('❌ Dibatalkan','success');renderOrders();renderJualanPesanan()}

async function renderDompet(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}const snap=await db.ref('warungdigital/orders').orderByChild('penjual').equalTo(currentUser).limitToLast(100).once('value');let total=0;const history=[];snap.forEach(c=>{const o=c.val();if(o.status==='verified'){total+=o.total;history.push(o)}});document.getElementById('walletSaldo').textContent=formatRp(total);const el=document.getElementById('walletHistory');if(history.length===0){el.innerHTML='<div class="empty"><p>Belum ada</p></div>';return}el.innerHTML=history.reverse().map(o=>`<div class="order-item"><div class="head"><div class="oid">${escapeHtml(o.produkNama)}</div><div class="status status-verified">+${formatRp(o.total)}</div></div><div class="body">👤 ${escapeHtml(o.pembeli)}</div></div>`).join('')}

function renderDownload(){const el=document.getElementById('downloadGrid');if(!el)return;const list=Object.entries(downloadItems).map(([id,v])=>({id,...v}));if(list.length===0){el.innerHTML='<div class="empty"><p>Belum ada file.</p></div>';return}el.innerHTML=list.reverse().map(d=>`<div class="download-card"><div class="thumb">${d.banner?`<img src="${cdnImg(d.banner,400)}">`:'☁️'}<div class="badge-free">FREE</div></div><div class="info"><div class="nama">${escapeHtml(d.nama)}</div><div class="uploader">👤 ${escapeHtml(d.uploader||'Anonim')}</div><div class="desk">${escapeHtml(d.deskripsi||'')}</div><button class="btn-dl" onclick="doDownload('${d.id}')">⬇️ Download</button></div></div>`).join('')}
function doDownload(id){const d=downloadItems[id];if(!d)return;const url=d.tipe==='link'?d.link:d.fileData;if(!url){showToast('File gak ada','error');return}db.ref('warungdigital/download/'+id+'/downloads').transaction(c=>(c||0)+1);window.open(url,'_blank');showToast('Link dibuka!','success')}
function showAddDownload(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}pendingDownloadBannerUrl='';pendingDownloadFileUrl='';openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>☁️ Upload Gratisan</h2><label>Nama</label><input type="text" id="dlNama" /><label>Deskripsi</label><textarea id="dlDesk" rows="3"></textarea><label>Tipe</label><select id="dlTipe" onchange="toggleDlTipe()"><option value="link">Link</option><option value="file">File</option></select><div id="dlLinkSection"><label>Link</label><input type="text" id="dlLink" /></div><div id="dlFileSection" class="hidden"><label>File (max 25MB)</label><input type="file" id="dlFile" onchange="uploadDlFile(this)" /></div><button class="btn btn-primary btn-block" onclick="saveDownload()">✅ Upload</button>`)}
function toggleDlTipe(){const t=document.getElementById('dlTipe').value;document.getElementById('dlLinkSection').classList.toggle('hidden',t!=='link');document.getElementById('dlFileSection').classList.toggle('hidden',t!=='file')}
async function uploadDlFile(input){const file=input.files[0];if(!file)return;showUploadProgress('Upload File');try{const res=await uploadToCloudinary(file,updateUploadProgress);pendingDownloadFileUrl=res.secure_url;pendingDownloadFileName=file.name;closeModal();setTimeout(showAddDownload,200)}catch(e){showToast('❌','error');closeModal()}}
async function saveDownload(){const nama=document.getElementById('dlNama').value.trim();const deskripsi=document.getElementById('dlDesk').value.trim();const tipe=document.getElementById('dlTipe').value;if(!nama){showToast('Nama wajib!','error');return}const data={nama,deskripsi,tipe,uploader:currentUser,createdAt:Date.now(),downloads:0,banner:pendingDownloadBannerUrl||''};if(tipe==='link'){const link=document.getElementById('dlLink').value.trim();if(!link){showToast('Link wajib!','error');return}data.link=link}else{if(!pendingDownloadFileUrl){showToast('Upload file dulu!','error');return}data.fileData=pendingDownloadFileUrl;data.fileName=pendingDownloadFileName}await db.ref('warungdigital/download').push(data);closeModal();showToast('✅ Upload berhasil!','success')}

function renderLevelPage(){if(!currentUser){document.getElementById('levelPageContent').innerHTML='<div class="empty"><p>Login dulu!</p></div>';return}updateLevelUI();document.getElementById('levelPageCount').textContent='Level '+userLevel}
function renderFlashSale(){const grid=document.getElementById('flashSaleGrid');if(!grid)return;const list=Object.entries(products).filter(([id,p])=>p.flashSale).map(([id,p])=>({id,...p}));document.getElementById('flashSaleCount').textContent=list.length;if(list.length===0){grid.innerHTML='<div class="empty"><p>Belum ada flash sale</p></div>';return}grid.innerHTML=list.map(p=>`<div class="product-card" onclick="showDetail('${p.id}')"><div class="thumb">${p.banner?`<img src="${cdnImg(p.banner,500)}">`:'📦'}<div class="badge-flash">🔥</div></div><div class="info"><div class="nama">${escapeHtml(p.nama)}</div><div class="harga">${formatRp(p.harga)}</div></div></div>`).join('')}

async function renderVoucher(){const el=document.getElementById('voucherList');if(!el)return;const snap=await db.ref('warungdigital/vouchers').once('value');const items=snap.val()||{};const now=Date.now();const list=Object.entries(items).map(([id,v])=>({id,...v}));const mine=list.filter(v=>v.penjual===currentUser);const others=list.filter(v=>v.penjual!==currentUser&&!v.used&&!v.expired);let html='';if(mine.length>0){html+='<div class="section-header" style="margin-bottom:12px"><h3 style="font-size:15px">📤 Voucher Saya</h3></div>';html+=mine.map(v=>{const expired=v.expired||(v.expiresAt&&now>v.expiresAt);return `<div class="voucher-card ${v.used?'used':''} ${expired?'expired':''}"><div class="voucher-code">${escapeHtml(v.kode)}</div><div class="voucher-disc">-${v.diskon}%</div><div class="voucher-info"><span>Pakai: ${v.usedCount||0}/${v.maxUse||99}</span><span>${expired?'❌':v.used?'✅':'🟢'}</span></div><button class="btn btn-danger btn-sm btn-block" onclick="deleteVoucher('${v.id}')" style="margin-top:8px">🗑️ Hapus</button></div>`}).join('')}if(others.length>0){html+='<div class="section-header" style="margin:20px 0 12px"><h3 style="font-size:15px">🎁 Voucher Tersedia</h3></div>';html+=others.map(v=>`<div class="voucher-card"><div class="voucher-code">${escapeHtml(v.kode)}</div><div class="voucher-disc">-${v.diskon}%</div><div class="voucher-info"><span>Dari: ${escapeHtml(v.penjual)}</span><span>Min: ${formatRp(v.minBeli||0)}</span></div><button class="btn btn-primary btn-sm btn-block" onclick="copyVoucherCode('${escapeHtml(v.kode)}')" style="margin-top:8px">📋 Copy</button></div>`).join('')}if(!html)html='<div class="empty"><p>Belum ada voucher</p></div>';el.innerHTML=html}
function showCreateVoucher(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>🎟️ Buat Voucher</h2><label>Kode</label><input type="text" id="vcKode" placeholder="PROMO10" style="text-transform:uppercase;font-family:'JetBrains Mono',monospace;letter-spacing:2px" /><label>Diskon (%)</label><input type="number" id="vcDiskon" value="10" min="1" max="90" /><label>Min Beli</label><input type="number" id="vcMinBeli" value="0" /><label>Max Pakai</label><input type="number" id="vcMaxUse" value="99" /><label>Expired (hari)</label><input type="number" id="vcExpDays" value="30" /><button class="btn btn-primary btn-block" onclick="saveVoucher()">✅ Buat</button>`)}
async function saveVoucher(){const kode=document.getElementById('vcKode').value.trim().toUpperCase().replace(/\s/g,'');const diskon=parseInt(document.getElementById('vcDiskon').value)||0;const minBeli=parseInt(document.getElementById('vcMinBeli').value)||0;const maxUse=parseInt(document.getElementById('vcMaxUse').value)||99;const expDays=parseInt(document.getElementById('vcExpDays').value)||30;if(!kode||kode.length<3){showToast('Kode min 3!','error');return}const snap=await db.ref('warungdigital/vouchers').orderByChild('kode').equalTo(kode).once('value');if(snap.exists()){showToast('Kode udah dipakai!','error');return}await db.ref('warungdigital/vouchers').push({kode,diskon,minBeli,maxUse,usedCount:0,used:false,expired:false,penjual:currentUser,expiresAt:Date.now()+expDays*86400000,createdAt:Date.now()});closeModal();showToast('✅ Voucher dibuat!','success');await checkAchievement('voucher_maker');renderVoucher()}
async function deleteVoucher(id){if(!confirm('Hapus?'))return;await db.ref('warungdigital/vouchers/'+id).remove();renderVoucher()}
function copyVoucherCode(kode){navigator.clipboard.writeText(kode);showToast('✅ Kode dicopy: '+kode,'success')}

async function toggleFollow(seller){if(!currentUser||isGuest){showToast('Login dulu!','error');return}if(seller===currentUser){showToast('Gak bisa follow sendiri!','error');return}const path='warungdigital/follows/'+currentUser+'/'+seller;const snap=await db.ref(path).once('value');if(snap.exists()){await db.ref(path).remove();delete userFollows[seller];showToast('Unfollowed','success')}else{await db.ref(path).set(true);userFollows[seller]=true;showToast('❤️ Followed!','success');await logMission('follow')}closeModal()}
async function renderFollowing(){const el=document.getElementById('followingList');if(!el)return;const snap=await db.ref('warungdigital/follows/'+currentUser).once('value');const items=snap.val()||{};const arr=Object.keys(items);document.getElementById('followingCount').textContent=arr.length;if(arr.length===0){el.innerHTML='<div class="empty"><p>Belum follow siapapun</p></div>';return}el.innerHTML=arr.map(name=>`<div class="account-item" onclick="showAccountDetail('${escapeHtml(name)}')"><div class="avatar">${name.charAt(0).toUpperCase()}</div><div class="info"><div class="nama">${escapeHtml(name)}</div></div></div>`).join('')}

async function renderStreak(){const el=document.getElementById('streakContent');if(!el)return;const current=userStreak.current||0;const max=userStreak.max||0;document.getElementById('streakCount').textContent='🔥 '+current+' hari';let days='';for(let i=1;i<=7;i++){const active=i<=current;const today=i===current;days+=`<div class="streak-day ${active?'active':''} ${today?'today':''}">${i}</div>`}el.innerHTML=`<div class="streak-card"><div class="streak-icon">🔥</div><div class="streak-num">${current}</div><div class="streak-lbl">hari berturut-turut (Max: ${max})</div><div class="streak-days">${days}</div></div>`}

async function renderAchievements(){const el=document.getElementById('achievementsContent');if(!el)return;const unlocked=Object.keys(userAchievements).length;document.getElementById('achCount').textContent=unlocked+'/'+ACHIEVEMENTS.length;el.innerHTML='<div class="badge-grid">'+ACHIEVEMENTS.map(a=>{const isUnlocked=userAchievements[a.id];return `<div class="badge-item ${isUnlocked?'unlocked':'locked'}"><div class="badge-icon">${a.icon}</div><div class="badge-name">${escapeHtml(a.name)}</div><div class="badge-desc">${escapeHtml(a.desc)}</div></div>`}).join('')+'</div>'}

async function renderStatistik(){const el=document.getElementById('statistikContent');if(!el)return;const ordersSnap=await db.ref('warungdigital/orders').once('value');let totalBeli=0,totalJual=0;ordersSnap.forEach(c=>{const o=c.val();if(o.pembeli===currentUser&&o.status==='verified')totalBeli+=o.total||0;if(o.penjual===currentUser&&o.status==='verified')totalJual+=o.total||0});const prodCount=Object.entries(products).filter(([id,p])=>p.penjual===currentUser).length;el.innerHTML=`<div class="tabungan-grid"><div class="tabungan-item"><div class="label">Total Belanja</div><div class="val">${formatRp(totalBeli)}</div></div><div class="tabungan-item"><div class="label">Total Jualan</div><div class="val">${formatRp(totalJual)}</div></div><div class="tabungan-item"><div class="label">Produk Saya</div><div class="val">${prodCount}</div></div><div class="tabungan-item"><div class="label">Level</div><div class="val">${userLevel}</div></div><div class="tabungan-item"><div class="label">EXP</div><div class="val">${userExp.toLocaleString('id-ID')}</div></div><div class="tabungan-item"><div class="label">Streak</div><div class="val">${userStreak.current||0} hari</div></div></div>`}

async function renderPromoWeb(){const el=document.getElementById('promoWebList');if(!el)return;const snap=await db.ref('warungdigital/promoweb').limitToLast(50).once('value');const items=snap.val()||{};const list=Object.entries(items).map(([id,v])=>({id,...v})).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));if(list.length===0){el.innerHTML='<div class="empty"><p>Belum ada promosi web</p></div>';return}el.innerHTML=list.map(p=>`<div class="promo-web-card" onclick="window.open('${escapeAttr(p.url||'')}','_blank')"><div class="pw-thumb">${p.banner?`<img src="${cdnImg(p.banner,500)}">`:'🔗'}</div><div class="pw-info"><div class="pw-title">${escapeHtml(p.judul||'Website')}</div><div class="pw-url">🔗 ${escapeHtml(p.url||'')}</div><div class="pw-url">👤 ${escapeHtml(p.user||'Anonim')}</div><button class="pw-btn" onclick="event.stopPropagation();window.open('${escapeAttr(p.url||'')}','_blank')">🌐 Kunjungi</button></div></div>`).join('')}
function showAddPromoWeb(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}pendingPwBanner='';openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>🔗 Tambah Promosi Web</h2><label>Judul</label><input type="text" id="pwJudul" /><label>URL</label><input type="text" id="pwUrl" placeholder="https://..." /><label>Banner (max 25MB)</label><input type="file" id="pwBanner" accept="image/*" onchange="uploadPromoWebBanner(this)" /><button class="btn btn-primary btn-block" onclick="savePromoWeb()">✅ Simpan</button>`)}
async function uploadPromoWebBanner(input){const file=input.files[0];if(!file)return;showUploadProgress('Upload Banner');try{const res=await uploadToCloudinary(file,updateUploadProgress);pendingPwBanner=res.secure_url;closeModal();setTimeout(showAddPromoWeb,200)}catch(e){showToast('❌','error');closeModal()}}
async function savePromoWeb(){const judul=document.getElementById('pwJudul').value.trim();const url=document.getElementById('pwUrl').value.trim();if(!judul||!url){showToast('Isi semua!','error');return}await db.ref('warungdigital/promoweb').push({judul,url,banner:pendingPwBanner||'',user:currentUser,createdAt:Date.now()});pendingPwBanner='';closeModal();showToast('✅ Ditambahkan!','success');renderPromoWeb()}

async function renderPrivateServer(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}const el=document.getElementById('psContent');if(!el)return;const snap=await db.ref('warungdigital/privateserver/'+currentUser).once('value');const ps=snap.val();let statusHtml='';if(ps&&ps.expiresAt&&!ps.permanent){const remaining=ps.expiresAt-Date.now();if(remaining>0){const days=Math.floor(remaining/86400000);const hours=Math.floor((remaining%86400000)/3600000);statusHtml=`<div class="ps-status-box"><div class="ps-title">✅ Aktif</div><div class="ps-value">${days}h ${hours}j</div></div>`}else{statusHtml='<div class="ps-status-box expired"><div class="ps-title">❌ EXPIRED</div><div class="ps-value">HABIS</div></div>'}}else if(ps&&ps.permanent){statusHtml='<div class="ps-status-box"><div class="ps-title">✅ PERMANENT</div><div class="ps-value">∞</div></div>'}else{statusHtml='<div class="help-info-box">Belum punya Private Server. Beli di bawah!</div>'}el.innerHTML=statusHtml+'<div class="section-header"><h2 style="font-size:18px">📋 List Harga</h2></div>'+PS_PRICES.map(p=>`<div class="ps-card"><div class="ps-info"><div class="ps-title">${escapeHtml(p.title)}</div><div class="ps-price">${p.price}P</div><div class="ps-desc">${escapeHtml(p.desc)}</div></div><button class="ps-btn" onclick="buyPrivateServer('${p.id}')">Beli</button></div>`).join('')+'<div class="section-header" style="margin-top:20px"><h2 style="font-size:18px">💬 Chat Dev</h2></div><button class="btn btn-primary btn-block" onclick="openChatWith(\''+DEV_NAME+'\')">💬 Chat Dev</button>'}
function buyPrivateServer(priceId){const price=PS_PRICES.find(p=>p.id===priceId);if(!price)return;openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>🌐 Beli Private Server</h2><div class="verify-box"><div class="label">Paket</div><div class="val">${escapeHtml(price.title)}</div><div class="label" style="margin-top:8px">Harga</div><div class="val big">${price.price}P</div></div><label>Request</label><textarea id="psRequest" rows="3" placeholder="Tulis request..."></textarea><button class="btn btn-primary btn-block" onclick="submitPSRequest('${priceId}')">✅ Kirim</button>`)}
async function submitPSRequest(priceId){const price=PS_PRICES.find(p=>p.id===priceId);const req=document.getElementById('psRequest').value.trim();if(!req){showToast('Tulis request!','error');return}const reqId='PS-'+Date.now();await db.ref('warungdigital/psRequests/'+reqId).set({user:currentUser,priceId,price:price.price,title:price.title,request:req,status:'pending',createdAt:Date.now()});closeModal();showToast('✅ Request terkirim ke Dev!','success')}

async function renderAccounts(){const el=document.getElementById('accountsList');if(!el)return;const snap=await db.ref('warungdigital/users').once('value');if(!snap.exists()){el.innerHTML='<div class="empty"><p>Belum ada akun</p></div>';return}const arr=[];snap.forEach(c=>{const nama=c.key;if(nama===currentUser)return;arr.push({nama,...c.val()})});arr.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));el.innerHTML=arr.map(u=>{const isDevUser=u.isDev||u.nama===DEV_NAME;return `<div class="account-item" onclick="showAccountDetail('${escapeHtml(u.nama)}')"><div class="avatar">${u.nama.charAt(0).toUpperCase()}</div><div class="info"><div class="nama">${escapeHtml(u.nama)} ${isDevUser?'👑':''}</div><div class="meta">Lv ${u.level||1} · ${(u.exp||0).toLocaleString('id-ID')} EXP</div></div></div>`}).join('')}
function showAccountDetail(nama){db.ref('warungdigital/users/'+nama).once('value',snap=>{const u=snap.val()||{};const isDevUser=u.isDev||nama===DEV_NAME;const myProducts=Object.entries(products).filter(([id,p])=>p.penjual===nama);const isFollowing=userFollows[nama];openModal(`<button class="close-btn" onclick="closeModal()">✕</button><div style="text-align:center;margin-bottom:16px"><div style="width:80px;height:80px;border-radius:50%;background:linear-gradient(135deg,#25d366,#6c5ce7);margin:0 auto;display:flex;align-items:center;justify-content:center;font-size:32px;color:#fff;font-weight:700">${nama.charAt(0).toUpperCase()}</div><h2 style="margin-top:12px">${escapeHtml(nama)} ${isDevUser?'👑':''}</h2><div style="font-size:13px;opacity:.7;margin-top:4px">Level ${u.level||1}</div></div><div class="tabungan-grid" style="margin-bottom:16px"><div class="tabungan-item"><div class="label">EXP</div><div class="val">${(u.exp||0).toLocaleString('id-ID')}</div></div><div class="tabungan-item"><div class="label">Produk</div><div class="val">${myProducts.length}</div></div></div><button class="btn btn-primary btn-block" onclick="closeModal();openChatWith('${escapeHtml(nama)}')">💬 Chat</button><button class="btn ${isFollowing?'btn-secondary':'btn-primary'} btn-block" onclick="toggleFollow('${escapeHtml(nama)}')">${isFollowing?'❤️ Unfollow':'🤍 Follow'}</button>`)})}

async function renderChatList(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}const el=document.getElementById('chatListContainer');const cc=document.getElementById('chatListCount');if(!el)return;const snap=await db.ref('warungdigital/chats').once('value');const rooms=[];snap.forEach(c=>{const roomId=c.key;if(roomId.includes(currentUser)){const other=roomId.split('_').find(u=>u!==currentUser);if(other){const msgs=c.val()?.messages||{};const arr=Object.values(msgs).sort((a,b)=>b.timestamp-a.timestamp);if(arr.length>0)rooms.push({other,lastMsg:arr[0]})}}});rooms.sort((a,b)=>b.lastMsg.timestamp-a.lastMsg.timestamp);if(cc)cc.textContent=rooms.length;if(rooms.length===0){el.innerHTML='<div class="empty"><p>Belum ada chat</p></div>';return}el.innerHTML=rooms.map(r=>{const preview=r.lastMsg.text||(r.lastMsg.file?'📎 File':'');return `<div class="account-item" onclick="openChatWith('${escapeHtml(r.other)}')"><div class="avatar">${r.other.charAt(0).toUpperCase()}</div><div class="info"><div class="nama">${escapeHtml(r.other)}</div><div class="meta">${escapeHtml(preview).substring(0,40)}</div></div></div>`}).join('')}
function openChatListFromBalloon(){showPage('chatlist');unreadChatCount=0;updateChatBalloon()}
function openChatWith(user){if(!currentUser||isGuest){showToast('Login dulu!','error');return}if(user===currentUser){showToast('Gak bisa chat sendiri!','error');return}currentChatUser=user;const roomId=[currentUser,user].sort().join('_');document.getElementById('chatName').textContent=user;document.getElementById('chatAvatar').textContent=user.charAt(0).toUpperCase();document.getElementById('chatBody').innerHTML='';document.getElementById('chatContainer').classList.add('show');if(chatRef)chatRef.off();chatRef=db.ref('warungdigital/chats/'+roomId+'/messages');chatRef.orderByChild('timestamp').limitToLast(100).on('value',snap=>{const body=document.getElementById('chatBody');if(!snap.exists()){body.innerHTML='<div style="text-align:center;padding:20px;opacity:.5;font-size:13px">Belum ada chat</div>';return}let html='';snap.forEach(c=>{const m=c.val();const isMe=m.from===currentUser;const time=new Date(m.timestamp).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});html+=`<div class="chat-msg ${isMe?'me':'other'}">`;if(m.file){if(m.fileType?.startsWith('image/'))html+=`<img src="${cdnImg(m.file,400)}">`;else html+=`<div><a href="${m.file}" target="_blank" style="color:inherit">${escapeHtml(m.fileName||'File')}</a></div>`}if(m.text)html+=`<div>${escapeHtml(m.text)}</div>`;html+=`<span class="time">${time}</span></div>`});body.innerHTML=html;body.scrollTop=body.scrollHeight});unreadChatCount=0;updateChatBalloon()}
function closeChat(){document.getElementById('chatContainer').classList.remove('show');if(chatRef){chatRef.off();chatRef=null}currentChatUser=null}
function sendChatMsg(){const input=document.getElementById('chatInput');const text=input.value.trim();if(!text||!currentChatUser)return;const roomId=[currentUser,currentChatUser].sort().join('_');db.ref('warungdigital/chats/'+roomId+'/messages').push({from:currentUser,text,timestamp:Date.now()}).then(()=>{input.value='';logMission('chat')})}
function attachChatFile(){if(!currentChatUser)return;const input=document.createElement('input');input.type='file';input.onchange=async e=>{const file=e.target.files[0];if(!file)return;showUploadProgress('Upload File');try{const res=await uploadToCloudinary(file,updateUploadProgress);closeModal();const roomId=[currentUser,currentChatUser].sort().join('_');await db.ref('warungdigital/chats/'+roomId+'/messages').push({from:currentUser,file:res.secure_url,fileType:file.type,fileName:file.name,timestamp:Date.now()});showToast('File terkirim!','success')}catch(e){showToast('❌','error');closeModal()}};input.click()}
function startUnreadChatListener(){if(!currentUser||isGuest)return;db.ref('warungdigital/chats').on('value',snap=>{let total=0;snap.forEach(room=>{const roomId=room.key;if(roomId.includes(currentUser)){const msgs=room.val()?.messages||{};Object.values(msgs).forEach(m=>{if(m.from!==currentUser&&!m.read)total++})}});unreadChatCount=total;updateChatBalloon()})}
function updateChatBalloon(){const badge=document.getElementById('chatBalloonBadge');const balloon=document.getElementById('chatBalloon');if(!badge||!balloon)return;if(currentUser&&!isGuest){balloon.classList.add('show')}else{balloon.classList.remove('show');return}if(unreadChatCount>0){badge.style.display='block';badge.textContent=unreadChatCount}else badge.style.display='none'}

function renderJualan(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}renderJualanProduk();renderJualanPesanan();renderJualanPembayaran()}
function switchJualanTab(tab,el){document.querySelectorAll('#page-jualan .tabs button').forEach(b=>b.classList.remove('active'));el.classList.add('active');['produk','pesanan','pembayaran'].forEach(t=>{const e=document.getElementById('jualan-'+t);if(e)e.classList.toggle('hidden',t!==tab)})}
async function renderJualanProduk(){const el=document.getElementById('jualan-produk');if(!el)return;if(!currentUser){el.innerHTML='<div class="empty"><p>Login dulu!</p></div>';return}const eSnap=await db.ref('warungdigital/users/'+currentUser+'/ewallets').once('value');const ewallets=eSnap.val()||[];let warningHtml='';if(ewallets.length===0){warningHtml='<div class="help-warn-box" style="margin-bottom:16px"><strong>⚠️ Daftarin E-Wallet dulu!</strong></div>'}const my=Object.entries(products).filter(([id,p])=>p.penjual===currentUser);if(my.length===0){el.innerHTML=warningHtml+'<div class="empty"><p>Belum ada produk</p></div>';return}el.innerHTML=warningHtml+'<div class="product-grid">'+my.map(([id,p])=>`<div class="product-card"><div class="thumb">${p.banner?`<img src="${cdnImg(p.banner,500)}">`:'📦'}</div><div class="info"><div class="nama">${escapeHtml(p.nama)}</div><div class="meta"><span class="stok">📦 ${p.stock!==undefined&&p.stock!==null?p.stock:'∞'}</span><span class="sold">🛒 ${p.sold||0}</span></div><div class="harga">${formatRp(p.harga)}</div><div style="display:flex;gap:6px;margin-top:10px"><button class="btn btn-sm btn-secondary" style="flex:1" onclick="toggleFlashSale('${id}')">${p.flashSale?'🔥':'💤'}</button><button class="btn btn-sm btn-danger" style="flex:1" onclick="deleteProduct('${id}')">🗑️</button></div></div></div>`).join('')+'</div>'}
async function toggleFlashSale(id){const p=products[id];if(!p)return;await db.ref('warungdigital/products/'+id).update({flashSale:!p.flashSale});renderJualanProduk()}
async function renderJualanPesanan(){const el=document.getElementById('jualan-pesanan');if(!el)return;const snap=await db.ref('warungdigital/orders').orderByChild('penjual').equalTo(currentUser).limitToLast(50).once('value');if(!snap.exists()){el.innerHTML='<div class="empty"><p>Belum ada penjualan</p></div>';return}const orders=[];snap.forEach(c=>orders.push({key:c.key,...c.val()}));orders.sort((a,b)=>b.createdAt-a.createdAt);el.innerHTML=orders.map(o=>renderOrderCard(o,'penjual')).join('')}
async function renderJualanPembayaran(){const el=document.getElementById('jualan-pembayaran');if(!el)return;const snap=await db.ref('warungdigital/users/'+currentUser).once('value');const u=snap.val()||{};const ewallets=u.ewallets||[];el.innerHTML=`<div class="form-group"><label>E-Wallet / Bank</label><div>${ewallets.length===0?'<div style="opacity:.5;text-align:center;padding:12px;font-size:13px">Belum ada</div>':ewallets.map((e,i)=>`<div class="cart-item" style="margin-bottom:8px"><div class="thumb">💳</div><div class="info"><div class="nama">${escapeHtml(e.jenis)}</div><div style="font-size:12px;opacity:.7">${escapeHtml(e.namaAkun)}</div><div style="font-size:12px;opacity:.7">${escapeHtml(e.nomor)}</div></div><button class="del" onclick="hapusEwallet(${i})">🗑️</button></div>`).join('')}</div><button class="btn btn-primary btn-block" onclick="showAddEwallet()">+ Tambah E-Wallet</button></div>`}
function showAddEwallet(){openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>💳 Tambah E-Wallet</h2><label>Jenis</label><select id="ewJenis"><option value="">-- Pilih --</option><option>DANA</option><option>OVO</option><option>GoPay</option><option>ShopeePay</option><option>BCA</option><option>BRI</option><option>BNI</option><option>Mandiri</option><option>Lainnya</option></select><label>Nama Akun</label><input type="text" id="ewNamaAkun" /><label>Nomor</label><input type="text" id="ewNomor" /><button class="btn btn-primary btn-block" onclick="simpanEwallet()">✅ Simpan</button>`)}
async function simpanEwallet(){const jenis=document.getElementById('ewJenis').value;const namaAkun=document.getElementById('ewNamaAkun').value.trim();const nomor=document.getElementById('ewNomor').value.trim();if(!jenis||!namaAkun||!nomor){showToast('Isi semua!','error');return}const snap=await db.ref('warungdigital/users/'+currentUser).once('value');const ewallets=snap.val()?.ewallets||[];ewallets.push({jenis,namaAkun,nomor,verified:true,createdAt:Date.now()});await db.ref('warungdigital/users/'+currentUser).update({ewallets});closeModal();showToast('✅ Ditambah!','success');renderJualanPembayaran()}
async function hapusEwallet(i){if(!confirm('Hapus?'))return;const snap=await db.ref('warungdigital/users/'+currentUser).once('value');const ewallets=snap.val()?.ewallets||[];ewallets.splice(i,1);await db.ref('warungdigital/users/'+currentUser).update({ewallets});renderJualanPembayaran()}
async function showAddProduct(){if(!currentUser||isGuest){showToast('Login dulu!','error');return}const eSnap=await db.ref('warungdigital/users/'+currentUser+'/ewallets').once('value');const ewallets=eSnap.val()||[];if(ewallets.length===0){showToast('Daftarin E-Wallet dulu!','error');return}pendingProductBannerUrl='';openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>+ Tambah Produk</h2><label>Tipe</label><select id="pType" onchange="toggleProductType()"><option value="digital">Digital (MediaFire)</option><option value="wa">WhatsApp</option></select><label>Nama</label><input type="text" id="pNama" /><label>Harga</label><input type="number" id="pHarga" /><label>Stok (kosong=unlimited)</label><input type="number" id="pStock" /><label>Kategori</label><select id="pKategori"><option>Umum</option><option>Top-Up Game</option><option>Template</option><option>E-book</option><option>Preset</option><option>Lainnya</option></select><label>Deskripsi</label><textarea id="pDeskripsi" rows="3"></textarea><div id="pDigitalSection"><label>Link MediaFire</label><input type="text" id="pLinkMediafire" /><label style="margin-top:12px">Banner</label><input type="file" id="pBanner" accept="image/*" onchange="uploadProductBanner(this)" /></div><div id="pWASection" class="hidden"><label>Nomor WA</label><input type="text" id="pWANumber" oninput="autoFillWA()" /><label>Link WA</label><input type="text" id="pWALink" readonly /></div><button class="btn btn-primary btn-block" onclick="saveProduct()">✅ Simpan</button>`)}
function toggleProductType(){const t=document.getElementById('pType').value;document.getElementById('pDigitalSection').classList.toggle('hidden',t!=='digital');document.getElementById('pWASection').classList.toggle('hidden',t!=='wa')}
function autoFillWA(){const num=document.getElementById('pWANumber').value.replace(/[^0-9]/g,'');document.getElementById('pWALink').value=num.length>=10?'https://wa.me/'+num:''}
async function uploadProductBanner(input){const file=input.files[0];if(!file)return;showUploadProgress('Upload Banner');try{const res=await uploadToCloudinary(file,updateUploadProgress);pendingProductBannerUrl=res.secure_url;closeModal();setTimeout(showAddProduct,200)}catch(e){showToast('❌','error');closeModal()}}
async function saveProduct(){const tipe=document.getElementById('pType').value;const nama=document.getElementById('pNama').value.trim();const harga=parseInt(document.getElementById('pHarga').value)||0;const stockInput=document.getElementById('pStock').value.trim();const stock=stockInput?parseInt(stockInput):null;const kategori=document.getElementById('pKategori').value;const deskripsi=document.getElementById('pDeskripsi').value.trim();const linkMediafire=document.getElementById('pLinkMediafire')?.value.trim()||'';const waLink=document.getElementById('pWALink')?.value.trim()||'';if(!nama||!harga){showToast('Nama & harga wajib!','error');return}if(tipe==='wa'&&!waLink){showToast('Nomor WA wajib!','error');return}if(tipe==='digital'&&!linkMediafire){showToast('Link MediaFire wajib!','error');return}await db.ref('warungdigital/products').push({nama,harga,kategori,deskripsi,stock,sold:0,views:0,penjual:currentUser,tipe,linkMediafire:tipe==='digital'?linkMediafire:'',waLink:tipe==='wa'?waLink:'',banner:pendingProductBannerUrl||'',createdAt:Date.now()});closeModal();pendingProductBannerUrl='';showToast('Produk ditambah!','success');await logMission('upload')}
async function deleteProduct(id){if(!confirm('Hapus?'))return;await db.ref('warungdigital/products/'+id).remove();showToast('Dihapus','success')}

function loadSettingAccount(){if(!currentUser)return;db.ref('warungdigital/users/'+currentUser).once('value',snap=>{const u=snap.val()||{};const n=document.getElementById('accNama');if(n)n.value=currentUser;const w=document.getElementById('accWA');if(w)w.value=u.wa||''})}
function saveSettingAccount(){const nama=document.getElementById('accNama').value.trim();const pass=document.getElementById('accPass').value.trim();const wa=document.getElementById('accWA').value.trim();if(!nama){showToast('Nama wajib!','error');return}const update={wa};if(pass)update.password=pass;db.ref('warungdigital/users/'+currentUser).update(update).then(()=>{showToast('Akun disimpan!','success');document.getElementById('accPass').value=''})}
async function requestNotifPermission(){if(!oneSignalReady){showToast('OneSignal belum siap','warn');return}try{await window.OneSignal.Notifications.requestPermission();showToast('✅ Izin diminta','success')}catch(e){showToast('❌','error')}}
function showHelp(){openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>❓ Help</h2><div class="help-info-box"><strong>WarungDigital v8.3.1</strong></div><div class="help-dev-box"><strong>Terminal Command:</strong><br>Ketik <code>Vmenu</code> di terminal untuk list semua command</div><button class="btn btn-primary btn-block" onclick="closeModal()">✅ Ngerti!</button>`)}
function showRequestFitur(){if(!currentUser){showToast('Login dulu!','error');return}openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>💡 Request</h2><label>Nama</label><input type="text" id="reqNama" value="${escapeAttr(currentUser||'')}" /><label>Fitur</label><textarea id="reqFitur" rows="3"></textarea><button class="btn btn-primary btn-block" onclick="submitRequestFitur()">📤 Kirim</button>`)}
function submitRequestFitur(){const nama=document.getElementById('reqNama').value.trim()||'Anonim';const fitur=document.getElementById('reqFitur').value.trim();if(!fitur){showToast('Tulis fitur!','error');return}db.ref('warungdigital/requests').push({nama,fitur,user:currentUser,timestamp:Date.now()}).then(()=>{closeModal();showToast('Request terkirim!','success')})}

function renderPromoJualan(){const track=document.getElementById('promoJualanTrack');if(!track)return;let html='';allPromoJualan.forEach(p=>{html+=`<div class="promo-slide" onclick="clickPromoJualan('${p.id}','${escapeAttr(p.user||'')}','${escapeAttr(p.produkId||'')}','${escapeAttr(p.link||'')}')">${p.banner?`<img src="${cdnImg(p.banner,400)}" loading="lazy" />`:'🏪'}<div class="slide-label">${escapeHtml(p.judul||p.user||'Promo')}</div></div>`});if(currentUser&&!isGuest){html+='<button class="promo-add-btn" onclick="showAddPromo(\'jualan\')">+<div>Tambah</div></button>'}if(allPromoJualan.length===0&&(!currentUser||isGuest)){html='<div style="padding:20px;opacity:.5;font-size:13px">Belum ada promo</div>'}track.innerHTML=html}
function clickPromoJualan(id,user,produkId,link){if(produkId&&products[produkId]){showDetail(produkId);return}if(link){window.open(link,'_blank');return}}
function renderPromoMedsos(){const track=document.getElementById('promoMedsosTrack');if(!track)return;let html='';allPromoMedsos.forEach(p=>{html+=`<div class="promo-slide" onclick="window.open('${escapeAttr(p.link||'')}','_blank')">${p.banner?`<img src="${cdnImg(p.banner,400)}" loading="lazy" />`:'📱'}<div class="slide-label">${escapeHtml(p.judul||'Sosmed')}</div></div>`});if(currentUser&&!isGuest){html+='<button class="promo-add-btn" onclick="showAddPromo(\'medsos\')">+<div>Tambah</div></button>'}if(allPromoMedsos.length===0&&(!currentUser||isGuest)){html='<div style="padding:20px;opacity:.5;font-size:13px">Belum ada promo sosmed</div>'}track.innerHTML=html}
function showAddPromo(jenis){if(!currentUser||isGuest){showToast('Login dulu!','error');return}pendingPromoBannerUrl='';const isJualan=jenis==='jualan';const myProducts=Object.entries(products).filter(([id,p])=>p.penjual===currentUser);openModal(`<button class="close-btn" onclick="closeModal();pendingPromoBannerUrl=''">✕</button><h2>+ Tambah Promo ${isJualan?'Jualan':'Sosmed'}</h2>${pendingPromoBannerUrl?`<img src="${cdnImg(pendingPromoBannerUrl,400)}" style="width:100%;border-radius:12px;margin-bottom:12px;max-height:150px;object-fit:cover" />`:''}<label>Judul</label><input type="text" id="promoJudul" /><label>Upload Banner</label><input type="file" id="promoBanner" accept="image/*" onchange="uploadPromoBanner(this,'${jenis}')" />${isJualan?`<label style="margin-top:12px">Link Produk</label><select id="promoProduk"><option value="">-- Pilih --</option>${myProducts.map(([id,p])=>`<option value="${id}">${escapeHtml(p.nama)}</option>`).join('')}</select><label style="margin-top:12px">Atau Link</label><input type="text" id="promoLink" />`:'<label style="margin-top:12px">Link</label><input type="text" id="promoLink" />'}<button class="btn btn-primary btn-block" onclick="savePromo('${jenis}')">✅ Simpan</button>`)}
async function uploadPromoBanner(input,jenis){const file=input.files[0];if(!file)return;showUploadProgress('Upload Banner');try{const res=await uploadToCloudinary(file,updateUploadProgress);pendingPromoBannerUrl=res.secure_url;closeModal();setTimeout(()=>showAddPromo(jenis),200)}catch(e){showToast('❌','error');closeModal()}}
async function savePromo(jenis){const judul=document.getElementById('promoJudul').value.trim();const link=document.getElementById('promoLink')?.value.trim()||'';const produkId=document.getElementById('promoProduk')?.value||'';if(!judul){showToast('Judul wajib!','error');return}if(!pendingPromoBannerUrl){showToast('Upload banner!','error');return}await db.ref('warungdigital/banners/'+(jenis==='jualan'?'promosiJualan':'promosiMedsos')).push({judul,banner:pendingPromoBannerUrl,user:currentUser,produkId,link,createdAt:Date.now()});pendingPromoBannerUrl='';closeModal();showToast('✅ Ditambahkan!','success');if(jenis==='jualan')loadPromoJualan();else loadPromoMedsos()}

async function renderDev(){if(!isDev){showToast('Dev only!','error');return}const el=document.getElementById('devContent');if(!el)return;const snap=await db.ref('warungdigital').once('value');const data=snap.val()||{};const users=data.users||{};const productsData=data.products||{};const orders=data.orders||{};let revenue=0;Object.values(orders).forEach(o=>{if(o.status==='verified')revenue+=o.total||0});el.innerHTML=`<div class="help-dev-box"><strong>👑 Dev Mode</strong></div><div class="stats"><div class="stat"><div class="num">${Object.keys(users).length}</div><div class="label">User</div></div><div class="stat"><div class="num">${Object.keys(productsData).length}</div><div class="label">Produk</div></div><div class="stat"><div class="num">${Object.keys(orders).length}</div><div class="label">Order</div></div><div class="stat"><div class="num">${formatRp(revenue)}</div><div class="label">Revenue</div></div></div><div class="tabs"><button class="active" onclick="switchDevTab('intro',this)">Intro</button><button onclick="switchDevTab('uiinfo',this)">Info</button><button onclick="switchDevTab('banner',this)">Banner</button><button onclick="switchDevTab('users',this)">User</button><button onclick="switchDevTab('broadcast',this)">BC</button></div><div id="dev-intro"></div><div id="dev-uiinfo" class="hidden"></div><div id="dev-banner" class="hidden"></div><div id="dev-users" class="hidden"></div><div id="dev-broadcast" class="hidden"></div>`;renderDevIntro(data.introWeb||{});renderDevUiInfo(data.uiInfo||{});renderDevBanner(data.settings||{});renderDevUsers(users);renderDevBroadcast()}
function switchDevTab(tab,el){document.querySelectorAll('#page-dev .tabs button').forEach(b=>b.classList.remove('active'));el.classList.add('active');['intro','uiinfo','banner','users','broadcast'].forEach(t=>{const e=document.getElementById('dev-'+t);if(e)e.classList.toggle('hidden',t!==tab)})}
function renderDevIntro(intro){const el=document.getElementById('dev-intro');if(!el)return;el.innerHTML=`<div class="help-dev-box"><strong>🎬 Intro</strong></div><div class="order-item"><div class="banner-dev" onclick="changeDevIntro()">${intro.media?`<img src="${cdnImg(intro.media,600)}" />`:'<div class="placeholder">📷<div>Klik upload</div></div>'}</div><button class="btn btn-danger btn-block" onclick="hapusDevIntro()">🗑️ Hapus</button></div>`}
function changeDevIntro(){const input=document.createElement('input');input.type='file';input.accept='image/*,video/mp4,video/webm';input.onchange=async e=>{const file=e.target.files[0];if(!file)return;showUploadProgress('Upload Intro');try{const res=await uploadToCloudinary(file,updateUploadProgress);await db.ref('warungdigital/introWeb').update({media:res.secure_url,mediaType:file.type.startsWith('video/')?'video':'image'});closeModal();showToast('✅','success');await loadIntroData();renderDev()}catch(e){showToast('❌','error');closeModal()}};input.click()}
function hapusDevIntro(){if(!confirm('Hapus?'))return;db.ref('warungdigital/introWeb').update({media:'',mediaType:''}).then(()=>renderDev())}
function renderDevUiInfo(uiInfo){const el=document.getElementById('dev-uiinfo');if(!el)return;const updates=uiInfo.updates?Object.entries(uiInfo.updates):[];el.innerHTML=`<div class="help-dev-box"><strong>📢 Info UI</strong></div><div class="order-item"><div class="form-group"><label>Judul</label><input type="text" id="uiInfoTitle" value="${escapeAttr(uiInfo.title||'WarungDigital v8.3.1')}" /></div><div class="form-group"><label>Subtitle</label><input type="text" id="uiInfoSubtitle" value="${escapeAttr(uiInfo.subtitle||'Marketplace Produk Digital')}" /></div><button class="btn btn-primary btn-block" onclick="simpanUiInfo()">✅ Simpan</button></div><div class="order-item"><div class="head"><div class="oid">📝 Update</div></div>${updates.map(([id,u])=>`<div class="income-item"><div class="info"><div class="nama">• ${escapeHtml(u)}</div></div><button class="del" onclick="hapusUiUpdate('${id}')">🗑️</button></div>`).join('')||'<div style="opacity:.5;font-size:13px;padding:8px">Belum ada</div>'}<div style="display:flex;gap:8px;margin-top:8px"><input type="text" id="newUiUpdate" placeholder="Update baru..." style="flex:1" /><button class="btn btn-primary btn-sm" onclick="tambahUiUpdate()">+</button></div></div>`}
function tambahUiUpdate(){const v=document.getElementById('newUiUpdate').value.trim();if(!v)return;db.ref('warungdigital/uiInfo/updates').push(v).then(()=>{showToast('Ditambah','success');renderDev()})}
function hapusUiUpdate(id){if(!confirm('Hapus?'))return;db.ref('warungdigital/uiInfo/updates/'+id).remove().then(()=>renderDev())}
function simpanUiInfo(){const title=document.getElementById('uiInfoTitle').value.trim();const subtitle=document.getElementById('uiInfoSubtitle').value.trim();db.ref('warungdigital/uiInfo').update({title,subtitle}).then(()=>showToast('Disimpan!','success'))}
function renderDevBanner(settings){const el=document.getElementById('dev-banner');if(!el)return;el.innerHTML=`<div class="help-dev-box"><strong>🖼️ Banner</strong></div>${bannerBlock('Banner 1:1','banner11',settings.banner11)}${bannerBlock('Banner Judul','bannerJudul',settings.bannerJudul)}${bannerBlock('Logo','bannerLogo',settings.bannerLogo)}${bannerBlock('Animasi RB','bannerAnimasi',settings.bannerAnimasi)}${bannerBlock('Background','bgWeb',settings.bgWeb)}${bannerBlock('Favicon','favicon',settings.favicon)}${bannerBlock('Loading BG','loadingBg',settings.loadingBg)}${bannerBlock('Loading Circle','loadingCircle',settings.loadingCircle)}`}
function bannerBlock(label,key,url){return `<div class="order-item"><div class="head"><div class="oid">${label}</div></div><div class="banner-dev" onclick="uploadBannerFile('${key}')">${url?`<img src="${cdnImg(url,600)}" />`:'<div class="placeholder">🖼️<div>Klik upload</div></div>'}</div><button class="btn btn-danger btn-block" onclick="hapusBanner('${key}')">🗑️ Hapus</button></div>`}
function uploadBannerFile(key){const input=document.createElement('input');input.type='file';input.accept='image/*';input.onchange=async e=>{const file=e.target.files[0];if(!file)return;showUploadProgress('Upload Banner');try{const res=await uploadToCloudinary(file,updateUploadProgress);const typeKey=key==='bgWeb'?'bgType':key+'Type';await db.ref('warungdigital/settings').update({[key]:res.secure_url,[typeKey]:file.type.startsWith('video/')?'video':'image'});closeModal();showToast('✅','success');await loadAllBannersAndBg();renderDev()}catch(e){showToast('❌','error');closeModal()}};input.click()}
function hapusBanner(key){if(!confirm('Hapus?'))return;const typeKey=key==='bgWeb'?'bgType':key+'Type';db.ref('warungdigital/settings').update({[key]:'',[typeKey]:''}).then(()=>{loadAllBannersAndBg();renderDev()})}
function renderDevUsers(users){const el=document.getElementById('dev-users');if(!el)return;const arr=Object.entries(users).map(([nama,u])=>({nama,...u})).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));el.innerHTML=arr.map(u=>`<div class="order-item"><div class="head"><div class="oid">${escapeHtml(u.nama)} ${u.isDev?'👑':''}</div></div><div class="body">Lv ${u.level||1} · ${(u.exp||0).toLocaleString('id-ID')} EXP</div><div class="actions"><button class="btn btn-sm btn-warning" onclick="devResetPassword('${escapeHtml(u.nama)}')">Reset Pass</button><button class="btn btn-sm btn-danger" onclick="showDevDeleteUser('${escapeHtml(u.nama)}')">🗑️ Hapus</button></div></div>`).join('')}
function devResetPassword(nama){const np=prompt('Password baru buat '+nama+':');if(!np||np.length<6){showToast('Min 6!','error');return}db.ref('warungdigital/users/'+nama).update({password:np}).then(()=>{db.ref('warungdigital/notifications').push({target:nama,title:'🔑 Password Direset',message:'Password baru: '+np,type:'info',from:'Developer',timestamp:Date.now(),read:false});showToast('✅','success')})}
function showDevDeleteUser(nama){if(nama===DEV_NAME){showToast('Gak bisa hapus dev!','error');return}if(!confirm('Hapus '+nama+'?'))return;db.ref('warungdigital/users/'+nama).remove().then(()=>{showToast('Dihapus','success');renderDev()})}
function renderDevBroadcast(){const el=document.getElementById('dev-broadcast');if(!el)return;el.innerHTML=`<div class="help-warn-box"><strong>📢 Broadcast</strong></div><div class="form-group"><label>Judul</label><input type="text" id="broadcastTitle" /></div><div class="form-group"><label>Isi</label><textarea id="broadcastMsg" rows="4"></textarea></div><button class="btn btn-primary btn-block" onclick="sendBroadcast()">📤 Kirim</button>`}
function sendBroadcast(){const title=document.getElementById('broadcastTitle').value.trim();const msg=document.getElementById('broadcastMsg').value.trim();if(!title||!msg){showToast('Isi semua!','error');return}db.ref('warungdigital/users').once('value',snap=>{const promises=[];snap.forEach(d=>{promises.push(db.ref('warungdigital/notifications').push({target:d.key,title,message:msg,type:'info',from:'Developer',timestamp:Date.now(),read:false}))});Promise.all(promises).then(()=>{showToast('✅ Terkirim!','success')})})}

function handleCommand(cmd){const input=document.getElementById('terminalInput');const c=cmd.trim();if(!c)return;input.value='';const parts=c.split(/\s+/);const main=parts[0];const args=parts.slice(1);pushLog('CMD',(isDev?'DEV > ':'> ')+c);const devCmds=['Vusers','Vbroadcast','Vsay','VkelolaserverDB','VtestserverDB','VconfirmPSuser','Vgiftprivateserver','Vresetopkhyah','Vcodeerror'];const secretCmds=['Vvirus','Vvirusoff','Vhint','Vopkhyah'];if(devCmds.includes(main)&&!isDev){pushLog('ERROR','Dev only');return}if(secretCmds.includes(main)&&!secretUnlocked){pushLog('ERROR','Secret belum di-unlock! Ketik Vsecret dulu.');return}
switch(main){
case 'Vmenu':pushLog('INFO','=== COMMAND ===');pushLog('INFO','Utility: Vmenu, Vclear, Vstats, Vtime, Vdate, Vping, Vuptime, Vversion, Vcodeerror');pushLog('INFO','User: Vwhoami, Vexp, Vlevel, Vrank');pushLog('INFO','Tools: Vcalc, Vsearch');if(isDev)pushLog('DEV','Dev: Vusers, Vbroadcast, Vsay, VkelolaserverDB, VtestserverDB, VconfirmPSuser, Vgiftprivateserver, Vresetopkhyah');if(secretUnlocked)pushLog('SECRET','Secret: Vvirus, Vvirusoff, Vhint, Vopkhyah');break;
case 'Vclear':logBuffer=[];renderTerminal();pushLog('OK','Cleared');break;
case 'Vstats':pushLog('INFO','Produk: '+Object.keys(products).length+' | Level: '+userLevel+' | EXP: '+userExp);break;
case 'Vtime':pushLog('INFO',new Date().toLocaleTimeString('id-ID'));break;
case 'Vdate':pushLog('INFO',new Date().toLocaleDateString('id-ID'));break;
case 'Vping':{const start=performance.now();db.ref('.info/connected').once('value').then(()=>{const ping=Math.round(performance.now()-start);let status=ping<300?'🟢 Bagus':ping<800?'🟡 Sedang':'🔴 Lambat';pushLog('OK','🏓 Pong! '+ping+'ms '+status)});break}
case 'Vuptime':pushLog('INFO','Uptime: '+Math.floor(performance.now()/1000)+'s');break;
case 'Vversion':pushLog('INFO','v8.3.1');break;
case 'Vwhoami':pushLog('INFO',currentUser?('User: '+currentUser+' | Lv'+userLevel+' | '+userExp+' EXP'):'Guest');break;
case 'Vexp':pushLog('INFO','EXP: '+userExp);break;
case 'Vlevel':pushLog('INFO','Level: '+userLevel+' - '+getLevelInfo(userLevel).name);break;
case 'Vrank':db.ref('warungdigital/users').once('value').then(snap=>{const arr=Object.entries(snap.val()||{}).map(([nama,u])=>({nama,exp:u.exp||0})).filter(u=>!u.isDev);arr.sort((a,b)=>b.exp-a.exp);const rank=arr.findIndex(u=>u.nama===currentUser)+1;if(rank>0)pushLog('OK','🏆 Rank: #'+rank+' dari '+arr.length)});break;
case 'Vcalc':try{const r=Function('"use strict";return('+args.join(' ')+')')();pushLog('OK','Hasil: '+r)}catch(e){pushLog('ERROR','Invalid')}break;
case 'Vsearch':window.open('https://www.google.com/search?q='+encodeURIComponent(args.join(' ')),'_blank');break;
case 'Vcodeerror':{pushLog('INFO','=== CODE ERROR LOG ===');if(errorLog.length===0){pushLog('OK','✅ Tidak ada error!')}else{pushLog('WARN','Total error: '+errorLog.length);errorLog.slice(-10).forEach(e=>{pushLog('ERROR',e.type.toUpperCase()+': '+e.msg)})}break}
case 'Vsecret':startSecretVerify();break;
case 'Vunlockabcsecret':{if(secretUnlocked){pushLog('SECRET','✅ Udah unlocked');break}if(Date.now()<secretLockUntil){pushLog('ERROR','Tunggu '+Math.ceil((secretLockUntil-Date.now())/1000)+'s');break}if(!secretVerifyPending){pushLog('WARN','Ketik Vsecret dulu');break}const userAns=parseInt(args[0]);if(userAns===secretAnswer){secretUnlocked=true;secretVerifyPending=false;localStorage.setItem('wd_secret_unlocked','true');pushLog('SECRET','🎉 UNLOCKED!');pushLog('SECRET','Coba: Vvirus, Vopkhyah');showToast('🎉 Secret terbuka!','success')}else{secretVerifyPending=false;secretLockUntil=Date.now()+30000;pushLog('ERROR','❌ Salah! Tunggu 30s')}break}
case 'Vvirus':startVirusFromCommand(args);break;
case 'Vvirusoff':stopVirus();break;
case 'Vhint':pushLog('SECRET','💡 Coba "Vvirus [user] [detik]" atau "Vopkhyah"');break;
case 'Vopkhyah':startOpkhyah();break;
case 'Vusers':db.ref('warungdigital/users').limitToLast(20).once('value').then(s=>{s.forEach(d=>{const u=d.val();pushLog('DEV',d.key+' - Lv'+(u.level||1))})});break;
case 'Vbroadcast':if(!args.length){pushLog('WARN','Usage: Vbroadcast pesan');break}db.ref('warungdigital/users').once('value',snap=>{const promises=[];snap.forEach(d=>{promises.push(db.ref('warungdigital/notifications').push({target:d.key,title:'📢 Dev',message:args.join(' '),type:'info',from:'Developer',timestamp:Date.now(),read:false}))});Promise.all(promises).then(()=>pushLog('OK','Broadcast terkirim'))});break;
case 'Vsay':showTopNotif('📢',args.join(' '),'info');break;
case 'VkelolaserverDB':{if(args[0]==='add'){const nama=args[1]||'Server Baru';openModal(`<button class="close-btn" onclick="closeModal()">✕</button><h2>🌐 Tambah Server</h2><label>Nama</label><input type="text" id="srvNama" value="${escapeAttr(nama)}" /><label>Max Users</label><input type="number" id="srvMax" value="5" /><label>Config JSON</label><textarea id="srvConfig" rows="6"></textarea><button class="btn btn-primary btn-block" onclick="submitAddServer('${escapeAttr(nama)}')">✅</button>`)}else if(args[0]==='list'){db.ref('warungdigital/servers').once('value').then(snap=>{const arr=Object.entries(snap.val()||{});if(arr.length===0)pushLog('INFO','Belum ada server');arr.forEach(([id,s])=>pushLog('DEV',id+' | '+s.name+' | '+Object.keys(s.users||{}).length+'/'+(s.maxUsers||5)))})}else if(args[0]==='remove'){db.ref('warungdigital/servers/'+args[1]).remove().then(()=>pushLog('DEV','Removed'))}else pushLog('INFO','Usage: VkelolaserverDB add/list/remove');break}
case 'VtestserverDB':{const id=args[0];if(!id){pushLog('WARN','Usage: VtestserverDB [id]');break}db.ref('warungdigital/servers/'+id).once('value').then(snap=>{if(!snap.exists()){pushLog('ERROR','Gak ada');return}const s=snap.val();pushLog('DEV','📋 '+s.name);try{const cfg=typeof s.config==='string'?JSON.parse(s.config):s.config;if(cfg.apiKey)pushLog('OK','✅ Config valid');else pushLog('WARN','Config kurang')}catch(e){pushLog('ERROR','Invalid JSON')}});break}
case 'VconfirmPSuser':if(args[0])confirmPSUser(args[0]);break;
case 'Vgiftprivateserver':{if(!args[0]||!args[1]){pushLog('WARN','Usage: Vgiftprivateserver [user] [harga] [waktu]');break}const target=args[0],harga=parseInt(args[1])||0,waktu=args[2]||'perm';const permanent=waktu==='perm';const expiresAt=permanent?0:Date.now()+parseInt(waktu)*86400000;db.ref('warungdigital/privateserver/'+target).set({giftedBy:currentUser,price:harga,title:'Gift Dev',expiresAt,permanent,createdAt:Date.now()}).then(()=>{db.ref('warungdigital/notifications').push({target,title:'🎁 Gift Private Server!',message:'Dari Dev: '+(permanent?'Permanent':waktu+' hari'),type:'info',from:'Developer',timestamp:Date.now(),read:false});pushLog('DEV','✅ Gift ke '+target)});break}
case 'Vresetopkhyah':localStorage.removeItem('wd_opkhyah_used');opkhyahUsed=false;pushLog('DEV','✅ Vopkhyah reset');break;
default:pushLog('ERROR','Gak dikenal: '+main+'. Ketik Vmenu')}}

async function submitAddServer(nama){const nm=document.getElementById('srvNama').value.trim()||nama;const maxU=parseInt(document.getElementById('srvMax').value)||5;const config=document.getElementById('srvConfig').value.trim();if(!config){showToast('Config wajib!','error');return}try{JSON.parse(config)}catch(e){showToast('❌ Config harus JSON valid!','error');return}const newId='ID_'+Math.random().toString(36).substr(2,8);await db.ref('warungdigital/servers/'+newId).set({name:nm,owner:currentUser,maxUsers:maxU,users:{},config,type:'firebase',createdAt:Date.now(),status:'active'});closeModal();pushLog('DEV','✅ Server '+newId+' dibuat');showToast('✅ Server '+newId+' aktif!','success')}
function confirmPSUser(reqId){const duration=prompt('Durasi (hari) / ketik "perm":','7');if(!duration)return;db.ref('warungdigital/psRequests/'+reqId).once('value',snap=>{const r=snap.val();if(!r)return;const permanent=duration==='perm';const expiresAt=permanent?0:Date.now()+parseInt(duration)*86400000;db.ref('warungdigital/psRequests/'+reqId).update({status:'confirmed',devMessage:'Dikonfirmasi',devTime:Date.now()}).then(()=>{db.ref('warungdigital/privateserver/'+r.user).set({giftedBy:currentUser,price:r.price,title:r.title,expiresAt,permanent,createdAt:Date.now()});db.ref('warungdigital/notifications').push({target:r.user,title:'✅ Private Server Aktif!',message:'Paket: '+r.title+(permanent?' (Permanent)':' ('+duration+' hari)'),type:'info',from:'Developer',timestamp:Date.now(),read:false});showToast('✅ PS diaktifkan!','success')})})}

function startSecretVerify(){if(Date.now()<secretLockUntil){pushLog('ERROR','Tunggu '+Math.ceil((secretLockUntil-Date.now())/1000)+'s');return}const a=Math.floor(Math.random()*100)+1;const b=Math.floor(Math.random()*100)+1;const ops=['+','-','×'];const op=ops[Math.floor(Math.random()*ops.length)];let answer;if(op==='+')answer=a+b;else if(op==='-')answer=a-b;else answer=a*b;secretAnswer=answer;secretVerifyPending=true;pushLog('SECRET','🔐 VERIFIKASI');pushLog('SECRET','Soal: '+a+' '+op+' '+b+' = ?');pushLog('SECRET','Jawab: Vunlockabcsecret <jawaban>');showToast('🔐 Jawab di terminal!','info')}

async function startVirusFromCommand(args){if(!currentUser){pushLog('ERROR','Login dulu');return}if(userLevel<5&&!isDev){pushLog('ERROR','Butuh Level 5+');return}const target=args[0];const duration=parseInt(args[1])||300;if(!target){pushLog('WARN','Usage: Vvirus [target] [detik]');return}if(target===DEV_NAME){pushLog('ERROR','Virus balik ke pengirim 😈');startVirus(Math.min(duration,300));return}const maxDur=isDev?900:300;const finalDur=Math.min(duration,maxDur);const tSnap=await db.ref('warungdigital/users/'+target).once('value');if(!tSnap.exists()){pushLog('ERROR','Target gak ada');return}if(tSnap.val().isDev){pushLog('ERROR','Target Dev!');return}db.ref('warungdigital/virus/'+target).set({from:currentUser,duration:finalDur,createdAt:Date.now(),active:true});pushLog('OK','😈 Virus ke '+target+' '+finalDur+'s!');showToast('😈 Terkirim ke '+target+'!','warn')}
function checkVirusOnLoad(){if(!currentUser)return;db.ref('warungdigital/virus/'+currentUser).once('value').then(snap=>{if(!snap.exists())return;const v=snap.val();if(v.active&&Date.now()-v.createdAt<v.duration*1000){const remaining=v.duration-Math.floor((Date.now()-v.createdAt)/1000);if(remaining>0)startVirus(remaining)}else db.ref('warungdigital/virus/'+currentUser).remove()})}
function startVirus(duration){if(virusActive)return;virusActive=true;virusDuration=duration;document.getElementById('virusOverlay').classList.add('show');for(let i=0;i<15;i++){setTimeout(()=>{if(!virusActive)return;const pop=document.createElement('div');pop.className='virus-popup';pop.textContent=['⚠️ VIRUS!','💀 HACKED','🔴 WARNING','☠️ ERROR','🚨 ALERT'][Math.floor(Math.random()*5)];pop.style.left=(Math.random()*80+5)+'%';pop.style.top=(Math.random()*80+5)+'%';document.getElementById('virusOverlay').appendChild(pop);setTimeout(()=>pop.remove(),1500)},i*200)}let countdown=duration;document.getElementById('virusCountdown').textContent=countdown;virusCountdownInterval=setInterval(()=>{countdown--;document.getElementById('virusCountdown').textContent=countdown;if(countdown<=0)stopVirus()},1000);virusTimer=setTimeout(stopVirus,duration*1000);showTopNotif('⚠️ VIRUS DETECTED','Ini cuma prank 😄','error')}
function stopVirus(){if(!virusActive)return;virusActive=false;document.getElementById('virusOverlay').classList.remove('show');document.querySelectorAll('.virus-popup').forEach(p=>p.remove());if(virusTimer)clearTimeout(virusTimer);if(virusCountdownInterval)clearInterval(virusCountdownInterval);if(currentUser)db.ref('warungdigital/virus/'+currentUser).remove();showToast('✅ Virus dimatikan','success')}

async function startOpkhyah(){if(!currentUser||isGuest){pushLog('ERROR','Login dulu');return}if(opkhyahActive){pushLog('WARN','Aktif!');return}if(opkhyahUsed&&!isDev){pushLog('WARN','🥚 Udah dipakai. 1x seumur hidup!');showToast('🥚 Cuma 1x!','warn');return}openModal(`<button class="close-btn" onclick="closeModal()">✕</button><div style="text-align:center;padding:20px 0"><div style="font-size:80px;margin-bottom:12px">🥚</div><h2 style="font-size:24px;color:#e74c3c;margin-bottom:12px">⚠️ VOPKHYAH ⚠️</h2><div class="help-warn-box" style="text-align:left;margin-bottom:16px"><strong>⚠️ PERINGATAN!</strong><br><br>🥚 Bakal bikin:<br>• 🌀 NGELAG PARAH<br>• 💀 SPAM VIRUS POPUP<br>• 📢 SPAM NOTIFIKASI<br>• 🔊 SOUND CHAOS<br><br><strong>🎁 HADIAH:</strong><br>Tahan 60 detik → <strong style="color:#25d366">+3 LEVEL!</strong><br><br><strong>❌ GAGAL kalau refresh/close</strong><br><br><strong style="color:#e74c3c">⚠️ CUMA 1X SEUMUR HIDUP!</strong></div><button class="btn btn-danger btn-block" onclick="confirmOpkhyah()" style="font-size:16px;padding:16px">🥚 YA, SAYA SIAP!</button><button class="btn btn-secondary btn-block" onclick="closeModal()">❌ Gak</button></div>`)}
function confirmOpkhyah(){closeModal();opkhyahActive=true;opkhyahRemaining=opkhyahDuration;opkhyahCompleted=false;localStorage.setItem('wd_opkhyah_used','true');opkhyahUsed=true;pushLog('SECRET','🥚 VOPKHYAH ACTIVATED!');showTopNotif('🥚 VOPKHYAH MODE','Tahan 60 detik!','error');document.getElementById('opkhyahTimer').classList.add('show');document.getElementById('opkCountdown').textContent=opkhyahRemaining;document.getElementById('opkProgressFill').style.width='0%';document.body.classList.add('opkhyah-body');document.getElementById('opkhyahOverlay').classList.add('show');opkhyahParticleInterval=setInterval(spawnOpkParticle,80);opkhyahPopupInterval=setInterval(spawnOpkPopup,250);opkhyahSoundInterval=setInterval(()=>{if(opkhyahActive)playTone([100,150,200,300,440][Math.floor(Math.random()*5)],0.08,'square',0.08)},400);opkhyahNotifInterval=setInterval(opkhyahSpamNotif,1000);opkhyahCountdownInterval=setInterval(()=>{opkhyahRemaining--;document.getElementById('opkCountdown').textContent=opkhyahRemaining;const pct=((opkhyahDuration-opkhyahRemaining)/opkhyahDuration)*100;document.getElementById('opkProgressFill').style.width=pct+'%';if(opkhyahRemaining<=0){clearInterval(opkhyahCountdownInterval);opkhyahWin()}},1000);opkhyahTimer=setTimeout(opkhyahWin,opkhyahDuration*1000+2000)}
function spawnOpkParticle(){if(!opkhyahActive)return;const el=document.getElementById('opkhyahOverlay');if(!el)return;const chars=['🥚','💀','⚠️','🌀','💥','🔥','⚡','🤖','👾','💣','☠️','🚨','❌','🔴'];const p=document.createElement('div');p.className='opk-particle';p.textContent=chars[Math.floor(Math.random()*chars.length)];p.style.left=Math.random()*100+'%';p.style.top=Math.random()*100+'%';p.style.fontSize=(16+Math.random()*40)+'px';el.appendChild(p);setTimeout(()=>p.remove(),3500);if(el.children.length>80)el.firstChild.remove()}
function spawnOpkPopup(){if(!opkhyahActive)return;const el=document.getElementById('opkhyahOverlay');if(!el)return;const msgs=['⚠️ ERROR','💀 HACKED','🥚 VOPKHYAH!','🔴 CRITICAL','☠️ FATAL','🚨 ALERT','💥 OVERLOAD','🌀 GLITCH'];const pop=document.createElement('div');pop.className='opk-popup';pop.textContent=msgs[Math.floor(Math.random()*msgs.length)];pop.style.left=(Math.random()*75+5)+'%';pop.style.top=(Math.random()*80+5)+'%';el.appendChild(pop);setTimeout(()=>pop.remove(),1200);if(el.children.length>100)el.firstChild.remove()}
async function opkhyahSpamNotif(){if(!opkhyahActive||!currentUser)return;const msgs=['💀 System Error','⚠️ Warning','🥚 Vopkhyah','🔥 CPU Overload','💥 Memory Leak','☠️ Kernel Panic'];showTopNotif(msgs[Math.floor(Math.random()*msgs.length)],'Tahan terus! Hadiah nunggu 🎁','error')}
async function opkhyahWin(){if(opkhyahCompleted)return;opkhyahCompleted=true;opkhyahActive=false;clearInterval(opkhyahParticleInterval);clearInterval(opkhyahPopupInterval);clearInterval(opkhyahSoundInterval);clearInterval(opkhyahNotifInterval);clearInterval(opkhyahCountdownInterval);clearTimeout(opkhyahTimer);document.getElementById('opkhyahTimer').classList.remove('show');document.body.classList.remove('opkhyah-body');const overlay=document.getElementById('opkhyahOverlay');overlay.classList.remove('show');overlay.innerHTML='';if(!opkhyahRewardGiven&&currentUser&&!isGuest){opkhyahRewardGiven=true;const oldLevel=userLevel;const targetLevel=Math.min(7,oldLevel+3);let targetExp=0;for(let i=0;i<targetLevel;i++)targetExp+=LEVELS[i].expNeed;targetExp+=100;const expDiff=Math.max(0,targetExp-userExp);if(expDiff>0){await db.ref('warungdigital/users/'+currentUser).update({exp:userExp+expDiff,level:targetLevel});userExp+=expDiff;userLevel=targetLevel}pushLog('SECRET','🥚 WIN! Level '+oldLevel+' → '+targetLevel);playSequence([{f:523,d:.15},{f:659,d:.15},{f:784,d:.2},{f:1047,d:.3},{f:1319,d:.4}]);openModal(`<button class="close-btn" onclick="closeModal()">✕</button><div class="opkhyah-win-modal"><div style="font-size:80px;margin-bottom:8px">🏆</div><h1>🎉 VOPKHYAH WIN! 🎉</h1><p style="font-size:15px;opacity:.95;margin-bottom:16px">Kamu berhasil nahan 60 detik!<br>HP kamu kuat 💪</p><div class="opk-reward">🥚➡️👑</div><div class="opk-level-text">Level ${oldLevel} → ${targetLevel}</div><div style="font-size:13px;opacity:.9;margin-bottom:8px">+${expDiff.toLocaleString('id-ID')} EXP</div><button class="btn btn-block" style="background:#fff;color:#25d366;font-weight:900;margin-top:12px" onclick="closeModal()">🎉 Mantap!</button></div>`);showTopNotif('🎉 VOPKHYAH WIN!','Naik 3 level!','success');await checkAchievement('vopkhyah')}updateLevelUI()}

window.addEventListener('beforeunload',function(){if(opkhyahActive&&!opkhyahCompleted){localStorage.setItem('wd_opkhyah_failed','true')}if(pendingCardData&&!pendingCardData.downloaded&&currentUser){localStorage.setItem('wd_pending_card','true')}});
if(localStorage.getItem('wd_opkhyah_failed')==='true'){localStorage.removeItem('wd_opkhyah_failed');setTimeout(()=>{if(currentUser)showTopNotif('❌ VOPKHYAH GAGAL','Kamu refresh/close','error')},2000)}
if(localStorage.getItem('wd_pending_card')==='true'&&currentUser){setTimeout(async()=>{const uSnap=await db.ref('warungdigital/users/'+currentUser).once('value');const u=uSnap.val();if(u&&u.password){const content=generateCardContent({nama:currentUser,password:u.password}).content;const blob=new Blob([content],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='warungdigital-card-'+currentUser+'.txt';document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);showToast('📄 Card auto-downloaded','info')}localStorage.removeItem('wd_pending_card')},2000)}
window.addEventListener('error',function(e){errorLog.push({type:'error',msg:e.message,file:e.filename,line:e.lineno,time:Date.now()});if(errorLog.length>50)errorLog.shift()});
window.addEventListener('unhandledrejection',function(e){errorLog.push({type:'promise',msg:String(e.reason),time:Date.now()});if(errorLog.length>50)errorLog.shift()});

(function(){['click','touchstart','keydown'].forEach(ev=>document.addEventListener(ev,function unlock(){try{const ctx=getAudioCtx();if(ctx&&ctx.state==='suspended')ctx.resume()}catch(e){}document.removeEventListener(ev,unlock)},{once:true}))})();

